    class CustomTween {
        constructor() {
            this.tweenList = [];
        }
        static to(node, props, duration, ease = Laya.Ease.linearNone) {
            let tween = new CustomTween();
            tween._node = node;
            tween.to(props, duration, ease);
            return tween;
        }
        static from(node, props, duration, ease = Laya.Ease.linearNone) {
            let tween = new CustomTween();
            tween._node = node;
            tween.from(props, duration, ease);
            return tween;
        }
        static delayTime(node, duration) {
            let tween = new CustomTween();
            tween._node = node;
            tween.delayTime(duration);
            return tween;
        }
        static scaleForever(node, scale1, scale2, duration, ease = Laya.Ease.linearNone) {
            let tween = CustomTween.to(node, { scaleX: scale1, scaleY: scale1 }, duration)
                .to({ scaleX: scale2, scaleY: scale2 }, duration)
                .start(0);
            return tween;
        }
        static roke(node, range = 5, speed = 200, interval = 1500, count = 0) {
            let tween = CustomTween.to(node, { rotation: range }, speed / 2)
                .to({ rotation: -range }, speed)
                .to({ rotation: range }, speed)
                .to({ rotation: 0 }, speed / 2)
                .to({ rotation: 0 }, interval)
                .start(count);
            return tween;
        }
        static rotateForever(node, duration = 5000, bClockwise = true) {
            let tween = CustomTween.to(node, { rotation: 360 * (bClockwise ? 1 : -1) }, duration)
                .callback(() => { node.rotation = 0; })
                .start(0);
            return tween;
        }
        static actionFloat(node, startValue, endValue, duration, callback, ease = Laya.Ease.linearNone) {
            let tween = new CustomTween();
            tween._node = node;
            tween.actionFloat(startValue, endValue, duration, callback, ease);
            return tween;
        }
        static bezierCurveMotion(pos1, pos2, pos3, node, duration) {
            let tween = new CustomTween();
            tween._node = node;
            tween.bezierCurveMotion(pos1, pos2, pos3, duration);
            return tween;
        }
        static heartBeat(node) {
            let scaleFactor1 = 1.1;
            let scaleFactor2 = 1.15;
            return CustomTween.to(node, { scaleX: node.scaleX * scaleFactor1, scaleY: node.scaleY * scaleFactor1 }, 100)
                .to({ scaleX: node.scaleX, scaleY: node.scaleY }, 100)
                .delayTime(50)
                .to({ scaleX: node.scaleX * scaleFactor2, scaleY: node.scaleY * scaleFactor2 }, 100)
                .to({ scaleX: node.scaleX, scaleY: node.scaleY }, 100)
                .delayTime(1300)
                .start(0);
        }
        static jumpTo(node, wPos, scale, duration = 300, endCallback) {
            let posX = node.x;
            let posY = node.y;
            let endPoint = node.parent.globalToLocal(wPos);
            let centerPos = new Laya.Vector2((posX + endPoint.x) / 2, (posY + endPoint.y) / 2 - 200);
            CustomTween.bezierCurveMotion(new Laya.Vector2(posX, posY), centerPos, endPoint, node, duration)
                .start(1);
            return CustomTween.to(node, { scaleX: scale, scaleY: scale }, duration, Laya.Ease.sineOut)
                .callback(() => {
                endCallback && endCallback();
            })
                .start(1);
        }
        to(props, duration, ease = Laya.Ease.linearNone) {
            let _tween = () => {
                this._curTween = Laya.Tween.to(this._node, props, duration, ease, new Laya.Handler(this, this._onComplete.bind(this)), 0, true, true);
            };
            this.tweenList.push(_tween);
            return this;
        }
        from(props, duration, ease = Laya.Ease.linearNone) {
            let _tween = () => {
                this._curTween = Laya.Tween.from(this._node, props, duration, ease, new Laya.Handler(this, this._onComplete.bind(this)), 0, true, true);
            };
            this.tweenList.push(_tween);
            return this;
        }
        callback(f) {
            let _tween = () => {
                f();
                this._onComplete();
            };
            this.tweenList.push(_tween);
            return this;
        }
        delayTime(duration) {
            let _tween = () => {
                Timer.callLater(duration / 1000, () => {
                    this._onComplete();
                }, this);
            };
            this.tweenList.push(_tween);
            return this;
        }
        bezierCurveMotion(pos1, pos2, pos3, duration) {
            let _tween = () => {
                let interval = 0;
                duration = duration / 1000;
                Timer.callLoop(0.016, (timer) => {
                    let f = interval / duration;
                    let cp1x = pos1.x * (1 - f) + pos2.x * f;
                    let cp1y = pos1.y * (1 - f) + pos2.y * f;
                    let cp2x = pos2.x * (1 - f) + pos3.x * f;
                    let cp2y = pos2.y * (1 - f) + pos3.y * f;
                    let x = cp1x * (1 - f) + cp2x * f;
                    let y = cp1y * (1 - f) + cp2y * f;
                    this._node.x = x;
                    this._node.y = y;
                    interval += Tools.delta();
                    if (interval >= duration) {
                        this._node.x = pos3.x;
                        this._node.y = pos3.y;
                        timer.stop();
                        this._onComplete();
                    }
                }, this);
            };
            this.tweenList.push(_tween);
            return this;
        }
        static bezierCurveMotionV3(pos1, pos2, pos3, duration, progresscallback) {
            let interval = 0;
            duration = duration / 1000;
            Timer.callLoop(0.016, (timer) => {
                let f = interval / duration;
                let cp1x = pos1.x * (1 - f) + pos2.x * f;
                let cp1y = pos1.y * (1 - f) + pos2.y * f;
                let cp1z = pos1.z * (1 - f) + pos2.z * f;
                let cp2x = pos2.x * (1 - f) + pos3.x * f;
                let cp2y = pos2.y * (1 - f) + pos3.y * f;
                let cp2z = pos2.z * (1 - f) + pos3.z * f;
                let x = cp1x * (1 - f) + cp2x * f;
                let y = cp1y * (1 - f) + cp2y * f;
                let z = cp1z * (1 - f) + cp2z * f;
                progresscallback(new Laya.Vector3(x, y, z));
                interval += Tools.delta();
                if (interval >= duration) {
                    timer.stop();
                }
            });
        }
        actionFloat(startValue, endValue, duration, callback, ease = Laya.Ease.linearNone) {
            let tween = () => {
                this._node["__action_float_value"] = startValue;
                this._onComplete();
            };
            let actionFloat = () => {
                callback(this._node["__action_float_value"]);
            };
            this.tweenList.push(tween);
            this.to({ __action_float_value: endValue, update: new Laya.Handler(this._node, actionFloat) }, duration, ease);
            return this;
        }
        repeat(count) {
            let repeatTweens = [];
            for (let i = 1; i < count; i++) {
                for (let index = 0; index < this.tweenList.length; index++) {
                    const element = this.tweenList[index];
                    repeatTweens.push(element);
                }
            }
            this.tweenList = this.tweenList.concat(repeatTweens);
            return this;
        }
        start(repeatCount = 1) {
            this.repeatCount = repeatCount;
            this._curIndex = -1;
            this._count = 0;
            this._onComplete();
            return this;
        }
        _onComplete() {
            if (!this._node || this._node.destroyed) {
                return;
            }
            this._curIndex++;
            if (this.tweenList[this._curIndex]) {
                this.tweenList[this._curIndex].call(this);
            }
            else {
                this._count++;
                if (this.repeatCount == 0 || this._count < this.repeatCount) {
                    this._curIndex = this._curIndex % this.tweenList.length;
                    this.tweenList[this._curIndex] && this.tweenList[this._curIndex].call(this);
                }
            }
        }
        stop() {
            this._curTween && this._curTween.pause();
        }
        resume() {
            this._curTween && this._curTween.resume();
        }
        clear() {
            this.tweenList = [];
        }
    }

    class Base64 {
        static encodeForUrl(input) {
            let str = this.encode(input);
            if (!str)
                return null;
            str = str.replace("+", "-");
            str = str.replace("/", "*");
            return str;
        }
        static decodeForUrl(input) {
            if (!input)
                return null;
            input = input.replace("-", "+");
            input = input.replace("*", "/");
            return this.decode(input);
        }
        static encode(input) {
            var output = "";
            var chr1, chr2, chr3, enc1, enc2, enc3, enc4;
            var i = 0;
            input = this._utf8_encode(input);
            while (i < input.length) {
                chr1 = input.charCodeAt(i++);
                chr2 = input.charCodeAt(i++);
                chr3 = input.charCodeAt(i++);
                enc1 = chr1 >> 2;
                enc2 = ((chr1 & 3) << 4) | (chr2 >> 4);
                enc3 = ((chr2 & 15) << 2) | (chr3 >> 6);
                enc4 = chr3 & 63;
                if (isNaN(chr2)) {
                    enc3 = enc4 = 64;
                }
                else if (isNaN(chr3)) {
                    enc4 = 64;
                }
                output = output +
                    this._keyStr.charAt(enc1) + this._keyStr.charAt(enc2) +
                    this._keyStr.charAt(enc3) + this._keyStr.charAt(enc4);
            }
            return output;
        }
        static decode(input) {
            var output = "";
            var chr1, chr2, chr3;
            var enc1, enc2, enc3, enc4;
            var i = 0;
            input = input.replace(/[^A-Za-z0-9\+\/\=]/g, "");
            while (i < input.length) {
                enc1 = this._keyStr.indexOf(input.charAt(i++));
                enc2 = this._keyStr.indexOf(input.charAt(i++));
                enc3 = this._keyStr.indexOf(input.charAt(i++));
                enc4 = this._keyStr.indexOf(input.charAt(i++));
                chr1 = (enc1 << 2) | (enc2 >> 4);
                chr2 = ((enc2 & 15) << 4) | (enc3 >> 2);
                chr3 = ((enc3 & 3) << 6) | enc4;
                output = output + String.fromCharCode(chr1);
                if (enc3 != 64) {
                    output = output + String.fromCharCode(chr2);
                }
                if (enc4 != 64) {
                    output = output + String.fromCharCode(chr3);
                }
            }
            output = this._utf8_decode(output);
            return output;
        }
        static _utf8_encode(string) {
            string = string.replace(/\r\n/g, "\n");
            var utftext = "";
            for (var n = 0; n < string.length; n++) {
                var c = string.charCodeAt(n);
                if (c < 128) {
                    utftext += String.fromCharCode(c);
                }
                else if ((c > 127) && (c < 2048)) {
                    utftext += String.fromCharCode((c >> 6) | 192);
                    utftext += String.fromCharCode((c & 63) | 128);
                }
                else {
                    utftext += String.fromCharCode((c >> 12) | 224);
                    utftext += String.fromCharCode(((c >> 6) & 63) | 128);
                    utftext += String.fromCharCode((c & 63) | 128);
                }
            }
            return utftext;
        }
        static _utf8_decode(utftext) {
            var string = "";
            var i = 0;
            var c = 0;
            var c1 = 0;
            var c2 = 0;
            var c3 = 0;
            while (i < utftext.length) {
                c = utftext.charCodeAt(i);
                if (c < 128) {
                    string += String.fromCharCode(c);
                    i++;
                }
                else if ((c > 191) && (c < 224)) {
                    c2 = utftext.charCodeAt(i + 1);
                    string += String.fromCharCode(((c & 31) << 6) | (c2 & 63));
                    i += 2;
                }
                else {
                    c2 = utftext.charCodeAt(i + 1);
                    c3 = utftext.charCodeAt(i + 2);
                    string += String.fromCharCode(((c & 15) << 12) | ((c2 & 63) << 6) | (c3 & 63));
                    i += 3;
                }
            }
            return string;
        }
    }
    Base64._keyStr = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";

    class ULEventListener {
        constructor(type, priority, callback, bDispatchOnce) {
            this.type = type;
            this.priority = priority;
            this.callback = callback;
            this.bDispatchOnce = bDispatchOnce;
            this.bNeedRemove = false;
        }
        isDispatchOnce() {
            return !!this.bDispatchOnce;
        }
        isNeedRemove() {
            return !!this.bNeedRemove;
        }
        markNeedRemove() {
            this.bNeedRemove = true;
        }
        triggerCallback(event) {
            if (this.callback instanceof Function) {
                try {
                    this.callback(event);
                }
                catch (error) {
                    console.error("ULEventListener.triggerCallback has exception!", error);
                    return false;
                }
                return true;
            }
            return false;
        }
    }

    class ULEvent {
        constructor(type, data) {
            this.bPropagationStoped = false;
            this.type = type;
            this.data = data;
            this.bPropagationStoped = false;
            this.returnValue = null;
        }
        stopImmediatePropagation() {
            this.bPropagationStoped = true;
        }
        setReturnValue(value, bDonotStop) {
            if (value != null) {
                this.returnValue = value;
                if (!bDonotStop)
                    this.stopImmediatePropagation();
            }
        }
        getReturnValue() {
            return this.returnValue;
        }
        isPropagationStoped() {
            return !!this.bPropagationStoped;
        }
    }

