    class mgrCop extends Manager {
        static onLoad() {
            super.onLoad();
            this.loadLocalCop();
            console.log("mgrCop.onLoad");
        }
        static loadRecord() {
            super.loadRecord();
        }
        static saveRecord() {
            super.saveRecord();
        }
        static loadLocalCop() {
            let localCop = {};
            let bUserTest = !window[`conch`] && !Laya.Browser.onAndroid && !Laya.Browser.onIOS && Laya.Browser.onPC;
            if (bUserTest) {
                console.log("-->: 使用测试cop");
            }
            else {
                console.log("-->: 使用默认cop");
            }
            mgrCfg.forDb("cop_db", (k, v) => {
                localCop[k] = v.defaultValue;
                if (bUserTest) {
                    localCop[k] = v.devtestValue;
                }
            });
            this.processCop(localCop);
            this.localCop = localCop;
            console.log("localCop:", localCop);
        }
        static processCop(cop) {
            console.log("mgrCop.processCop");
            mgrCfg.forDb("cop_process_db", (k, v) => {
                let value = cop[k];
                if (value == null) {
                    return;
                }
                let arr = value.split(v.splitChar) || [];
                console.log("  process", k, arr);
                for (let i = 0; i < v.outputFieldNames.length; i++) {
                    const fieldName = v.outputFieldNames[i];
                    let fieldValue = arr[i];
                    if (fieldValue == null) {
                        console.warn(ul.format("mgrCop.processCop fieldValue not found! index = %d, fieldName = %s", i, fieldName));
                    }
                    else {
                        console.log(`  set ${fieldName}, ${fieldValue}`);
                        cop[fieldName] = fieldValue;
                    }
                }
            });
        }
        static get(key) {
            let cop = "";
            let value = this.remoteCop[key];
            if (value != null) {
                cop = value;
            }
            else {
                cop = this.localCop[key];
            }
            return cop;
        }
        static getNumberValue(key) {
            let value = this.get(key);
            if (value == null)
                return 0;
            let number = parseFloat(value);
            if (isNaN(number))
                return 0;
            return number;
        }
        static getBooleanValue(key) {
            let value = this.get(key);
            if (value == null)
                return false;
            value = value.toLowerCase();
            return value == "1" || value == "true";
        }
        static getCops() {
            let cops = {};
            if (Tools.getObjSize(this.localCop) == 0) {
                this.loadLocalCop();
            }
            Tools.forEachMap(this.localCop, (k, v) => {
                cops[k] = v;
            });
            Tools.forEachMap(this.remoteCop, (k, v) => {
                cops[k] = v;
            });
            return cops;
        }
        static setRemoteValue(key, value) {
            if (key == null) {
                console.warn("mgrCop.setRemoteValue key not found!");
                return;
            }
            this.remoteCop[key] = value;
            this.processCop(this.remoteCop);
        }
        static onReceiveSdkCop(configInfo) {
            console.log("mgrCop.onReceiveSdkCop");
            this.remoteCop = JSON.parse(configInfo || "") || {};
            this.processCop(this.remoteCop);
        }
    }
