    mgrCop.remoteCop = {};
    mgrCop.sdkCop = {};

    class ScaleButton extends Laya.Script {
        constructor() {
            super();
            this.bTween = true;
            this.bTouchBegin = false;
            this.bPlaySoundEffect = true;
        }
        get __node() {
            return this.owner;
        }
        static setSoundPlayId(soundId) {
            this.generalSoundId = soundId;
        }
        onDisable() {
        }
        onMouseDown(e) {
            this.bTouchBegin = true;
            this.onTouchBegin(e);
        }
        onMouseUp(e) {
            this.bTouchBegin = false;
            this.onTouchEnd(e);
        }
        onMouseOut(e) {
            if (!this.bTouchBegin)
                return;
            this.bTouchBegin = false;
            this.onTouchCancle(e);
        }
        onClick(e) {
            if (this.fOnClick instanceof Function) {
                this.fOnClick(e);
            }
            if (ScaleButton.generalSoundId && this.bPlaySoundEffect)
                mgrSound.play(ScaleButton.generalSoundId);
        }
        onTouchBegin(e) {
            if (!this.bTween)
                return;
            Laya.Tween.to(this.owner, { scaleX: 0.9, scaleY: 0.9 }, 50);
        }
        onTouchEnd(e) {
            this.onTouchCancle(e);
        }
        onTouchCancle(e) {
            if (!this.bTween)
                return;
            Laya.Tween.to(this.owner, { scaleX: 1, scaleY: 1 }, 50, Laya.Ease.backOut);
        }
    }

