    class ULSkeleton extends Laya.Sprite {
        constructor(path, loadedCallback, frameRate = 60) {
            super();
            this.path = path;
            this.loadedCallback = loadedCallback;
            let templet = ULSkeleton.allTemplets[path];
            let bLoading = !!ULSkeleton.loadingTemplets[path];
            if (templet && !bLoading) {
                this.templet = templet;
                this.parseComplete();
                return;
            }
            else {
                if (!templet) {
                    templet = new Laya.Templet();
                    templet.rate = frameRate;
                    templet.on(Laya.Event.COMPLETE, this, this.parseComplete);
                    templet.on(Laya.Event.ERROR, this, this.onError);
                    templet.loadAni(path);
                    this.templet = templet;
                }
                else {
                    templet.on(Laya.Event.COMPLETE, this, this.parseComplete);
                    templet.on(Laya.Event.ERROR, this, this.onError);
                    this.templet = templet;
                }
            }
        }
        onError() {
            console.log("骨骼动画初始化 parse error");
        }
        parseComplete() {
            console.log("骨骼动画初始化 成功!!!");
            let skeleton;
            skeleton = this.templet.buildArmature(0);
            this.templet.lock = true;
            skeleton.showSkinByName("normal");
            this.addChild(skeleton);
            this.bLoaded = true;
            this.skeleton = skeleton;
            ULSkeleton.allTemplets[this.path] = this.templet;
            if (this.playingAnimationName)
                this.playAnimation(this.playingAnimationName, this.bPlayingLoop, this.playEndCallback);
            if (this.playingBackRate)
                this.playbackRate(this.playingBackRate);
            this.loadedCallback && this.loadedCallback();
        }
        playAnimation(name, loop = true, playEndCallback) {
            this.bPlayingLoop = loop;
            this.playingAnimationName = name;
            this.playEndCallback = playEndCallback;
            if (!this.bLoaded)
                return;
            this.skeleton.play(this.playingAnimationName, loop);
            this.playEndCallback && Timer.callLater(this.skeleton.player.playDuration / 1000, () => {
                let temp = this.playEndCallback;
                this.playEndCallback = null;
                temp && temp();
            }, this);
        }
        playbackRate(value) {
            this.playingBackRate = value;
            if (!this.bLoaded)
                return;
            this.skeleton.playbackRate(this.playingBackRate);
        }
        static create(spineId, loadedCallback, frameRate = 60) {
            let spineData = mgrCfg.get_from_spine_db(spineId);
            if (!spineData)
                return null;
            return new ULSkeleton(spineData.path, loadedCallback, frameRate);
        }
    }
    ULSkeleton.allTemplets = {};
    ULSkeleton.loadingTemplets = {};

    class syncAnimationCom extends Laya.Script3D {
        onLateUpdate() {
            let owner = this.owner;
            if (!owner.baseBody)
                return;
            for (const k in owner.parts) {
                let partInfo = owner.parts[k];
                if (!partInfo)
                    continue;
                let partData = mgrCfg.get_from_part_db(partInfo.partId);
                let partTypeData = mgrCfg.get_from_part_type_db(partData.type);
                if (!!partTypeData.linkPoint)
                    continue;
                for (let i = 0; i < partInfo.nodes.length; i++) {
                    const nodeInfo = partInfo.nodes[i];
                    Tools.syncNodeATransform2NodeBTransform(owner.baseBody.getChildAt(0), nodeInfo.node.getChildAt(0), /Guadian/);
                }
            }
        }
    }

    class ShadowFollow extends Laya.Script {
        constructor() {
            super();
            this.__node = null;
            this.scaleMin = 0;
            this.scaleMax = 1;
        }
        onAwake() {
            this.__node = this.owner;
        }
        onDisable() {
        }
        onLateUpdate() {
            if (!this.__node)
                return;
            if (!this.__target || this.__target.destroyed)
                return;
            let pos = this.__target.transform.position.clone();
            pos.y = 0.01;
            this.__node.transform.position = pos;
            this.__node.transform.rotationEuler = new Laya.Vector3(90);
            let disTarget = this.__target.getChildByName("Bip001");
            if (!disTarget)
                return;
            disTarget = disTarget.getChildAt(0);
            if (!disTarget)
                return;
            disTarget = disTarget.getChildAt(2);
            if (!disTarget)
                return;
            let distance = disTarget.transform.position.y + 0.3;
            let factor = distance / 2;
            let scale = this.scaleMin * factor + this.scaleMax * (1 - factor);
            this.__node.transform.scale = new Laya.Vector3(scale, scale, scale);
        }
    }

    class RoleAvatar extends Laya.Sprite3D {
        constructor() {
            super();
            this.unloadedPartIds = {};
            this.loadingPartIds = {};
            this.loadEndCallBacks = [];
            this.allLoadEndCallBacks = [];
            this.linkedModels = [];
            this.parts = {};
            this.loadDefault(() => {
                Timer.callLoop(0.001, this.loadPart.bind(this), this);
            });
            this.addComponent(syncAnimationCom);
        }
        get bLoading() {
            return this.bLoadingNakedness || this.bLoadingPart || ul.length(this.unloadedPartIds) > 0;
        }
        destroy() {
            for (let i = 0; i < this.linkedModels.length; i++) {
                const element = this.linkedModels[i];
                this.unlinkModel(element);
            }
            for (const k in this.parts) {
                let partInfo = this.parts[k];
                if (!partInfo)
                    continue;
                let nodeInfos = partInfo.nodes;
                for (let i = 0; i < nodeInfos.length; i++) {
                    const nodeInfo = nodeInfos[i];
                    mgrLoader.Pool.recoverModel(nodeInfo.node);
                }
            }
            this.parts = {};
            if (this.baseBody) {
                mgrLoader.Pool.recoverModel(this.baseBody);
            }
            if (this.shadow) {
                mgrLoader.Pool.recoverModel(this.shadow);
            }
            super.destroy(false);
        }
        loadDefault(finishCallback) {
            this.bLoadingNakedness = true;
            let preModelIds = [MODEL_ID.role_body, MODEL_ID.shadow];
            let taskSamples = [];
            for (let index = 0; index < preModelIds.length; index++) {
                const modelId = preModelIds[index];
                taskSamples.push((endCallback) => {
                    mgrLoader.loadModeWithModeId(modelId, (bSuccessful) => {
                        endCallback();
                    }, this, 1);
                });
            }
            let taskManager = new TaskManager();
            taskManager.push(taskSamples);
            let loadEndCallback = () => {
                for (let i = 0; i < preModelIds.length; i++) {
                    const modelId = preModelIds[i];
                    let mode = mgrLoader.Pool.getModel(modelId);
                    mode.active = true;
                    let animator = mode.getComponent(Laya.Animator);
                    if (modelId == MODEL_ID.role_body) {
                        this.baseBody = mode;
                        this.baseBodyAnimator = animator;
                        this.addChild(mode);
                        this.baseBodyMaterials = mgrMaterial.setCartonShader(mode, MODEL_ID.role_body);
                        if (this.shadow) {
                            let comp = this.shadow.addComponent(ShadowFollow);
                            comp.__target = this.baseBody;
                        }
                    }
                    ;
                    if (modelId == MODEL_ID.shadow) {
                        this.shadow = mode;
                        this.shadow.transform.position = new Laya.Vector3(0, 0.01);
                        this.addChild(mode);
                        this.shadowMaterials = mgrMaterial.setCartonShader(mode, MODEL_ID.shadow);
                        if (this.baseBody) {
                            let comp = this.shadow.addComponent(ShadowFollow);
                            comp.__target = this.baseBody;
                        }
                    }
                }
                let defaultPartIds = [];
                mgrCfg.forDb_from_part_type_db((k, v) => {
                    if (v.defaultPartId && !this.unloadedPartIds[v.id]) {
                        defaultPartIds.push(v.defaultPartId);
                    }
                });
                this.fillByPartIds(defaultPartIds);
                this.bLoadingNakedness = false;
            };
            taskManager.start(() => {
                loadEndCallback();
                finishCallback();
            });
        }
        fillByPartIds(partIds) {
            for (let i = 0; i < partIds.length; i++) {
                const partId = partIds[i];
                let partData = mgrCfg.get_from_part_db(partId);
                this.unloadedPartIds[partData.type] = partId;
            }
            console.log(this.unloadedPartIds);
        }
        removePart(partId) {
            let partData = mgrCfg.get_from_part_db(partId);
            let oldPartInfo = this.parts[partData.type];
            if (oldPartInfo) {
                console.log(`移除部件: ${oldPartInfo.partId}`);
                for (let index = 0; index < oldPartInfo.nodes.length; index++) {
                    const element = oldPartInfo.nodes[index];
                    mgrLoader.Pool.recoverModel(element.node);
                }
                this.parts[partData.type] = null;
            }
        }
        registerLoadEndCallback(callback) {
            this.loadEndCallBacks.push(callback);
            return this;
        }
        registerAllLoadEndCallback(callback) {
            this.allLoadEndCallBacks.push(callback);
            return this;
        }
        loadPart() {
            let mustRequiredPartTypes = [PartType.cloth, PartType.wing, PartType.face, PartType.hair];
            let allPartTypes = [PartType.cloth, PartType.hair, PartType.shoe, PartType.sock, PartType.wing, PartType.headDec, PartType.handDec, PartType.face];
            let allNeedFinishedCount = 0;
            let allFinishedCount = 0;
            for (let i = 0; i < mustRequiredPartTypes.length; i++) {
                const partType = mustRequiredPartTypes[i];
                if (!this.loadingPartIds[partType] && !this.unloadedPartIds[partType]) {
                    allNeedFinishedCount++;
                }
            }
            if (allNeedFinishedCount == mustRequiredPartTypes.length) {
                for (let index = 0; index < this.loadEndCallBacks.length; index++) {
                    const callback = this.loadEndCallBacks[index];
                    Timer.callLater(0.1, () => {
                        callback && callback();
                    }, true);
                }
                this.loadEndCallBacks = [];
            }
            for (let i = 0; i < allPartTypes.length; i++) {
                const partType = allPartTypes[i];
                if (!this.loadingPartIds[partType] && !this.unloadedPartIds[partType]) {
                    allFinishedCount++;
                }
            }
            if (allFinishedCount == allPartTypes.length) {
                for (let index = 0; index < this.allLoadEndCallBacks.length; index++) {
                    const callback = this.allLoadEndCallBacks[index];
                    Timer.callLater(0.1, () => {
                        callback && callback();
                    }, true);
                }
                this.allLoadEndCallBacks = [];
            }
            if (this.bLoadingPart)
                return;
            if (ul.length(this.unloadedPartIds) <= 0) {
                return;
            }
            this.loadingPartIds = this.unloadedPartIds;
            this.unloadedPartIds = {};
            this.bLoadingPart = true;
            let mustRequiredPartIds = [];
            let otherPartIds = [];
            for (const k in this.loadingPartIds) {
                let partId = this.loadingPartIds[k];
                if (!partId)
                    continue;
                let partData = mgrCfg.get_from_part_db(partId);
                if (mustRequiredPartTypes.indexOf(partData.type) >= 0) {
                    mustRequiredPartIds.push(partId);
                }
                else {
                    otherPartIds.push(partId);
                }
            }
            let tManager = new TaskManager();
            let tSamples = [];
            tSamples.push((finishCallback) => {
                let finishedCount = 0;
                for (let i = 0; i < mustRequiredPartIds.length; i++) {
                    let partId = mustRequiredPartIds[i];
                    let partData = mgrCfg.get_from_part_db(partId);
                    mgrLoader.loadModeWithModeId(partData.modelId, (bsuccessful) => {
                        this.replaceLoadedPart(partId);
                        finishedCount++;
                        if (finishedCount == mustRequiredPartIds.length) {
                            finishCallback();
                        }
                    }, this, 1);
                }
                if (mustRequiredPartIds.length == 0) {
                    finishCallback();
                }
            });
            tManager.push(tSamples);
            tSamples = [];
            tSamples.push((finishCallback) => {
                let finishedCount = 0;
                for (let i = 0; i < otherPartIds.length; i++) {
                    let partId = otherPartIds[i];
                    let partData = mgrCfg.get_from_part_db(partId);
                    mgrLoader.loadModeWithModeId(partData.modelId, (bsuccessful) => {
                        this.replaceLoadedPart(partId);
                        finishedCount++;
                        if (finishedCount == otherPartIds.length) {
                            finishCallback();
                        }
                    }, this, 1);
                }
                if (otherPartIds.length == 0) {
                    finishCallback();
                }
            });
            tManager.push(tSamples);
            tSamples = [];
            tManager.start(() => {
                this.bLoadingPart = false;
                this.loadingPartIds = {};
            });
        }
        replaceLoadedPart(partId) {
            let partData = mgrCfg.get_from_part_db(partId);
            this.loadingPartIds[partData.type] = null;
            let oldPartInfo = this.parts[partData.type];
            if (oldPartInfo) {
                for (let index = 0; index < oldPartInfo.nodes.length; index++) {
                    const element = oldPartInfo.nodes[index];
                    mgrLoader.Pool.recoverModel(element.node);
                }
                this.parts[partData.type] = null;
            }
            console.log(`添加部件: ${partData.name}`);
            let mode = mgrLoader.Pool.getModel(partData.modelId);
            mode.active = true;
            mode.transform.scale = new Laya.Vector3(1, 1, 1);
            let animator = mode.getComponent(Laya.Animator);
            if (!animator) {
                animator = mode.addComponent(Laya.Animator);
            }
            let materials = this.useCartonMaterial(mode, partId);
            let partTypeData = mgrCfg.get_from_part_type_db(partData.type);
            if (partTypeData.linkPoint || partData.assignLinkPoint) {
                Tools.link2Node(partData.assignLinkPoint || partTypeData.linkPoint, this.baseBody, mode);
            }
            else {
                this.addChild(mode);
                Tools.syncNodeA2NodeB(this.baseBody.getChildAt(0), mode.getChildAt(0), /Guadian/);
            }
            mgrMaterial.useDynamicBone(mode, partData.modelId);
            partData.assignAnimation && this.playAnimation(partData.assignAnimation);
            this.parts[partData.type] = {
                partId: partId,
                nodes: [{
                        node: mode,
                        animator: animator,
                        materials: materials,
                    }]
            };
            if (partData.type == PartType.wing) {
                let levelData = mgrCfg.get_from_role_level_db(mgrInteraction.level);
                if (this.wingScale == null) {
                    this.wingScale = levelData.wingScale;
                }
                else {
                    this.wingScale = this.wingScale;
                }
                if (this.wingOffset == null) {
                    this.wingOffset = levelData.wingOffset;
                }
                else {
                    this.wingOffset = this.wingOffset;
                }
            }
        }
        isPlayFinished() {
            let playState = this.baseBodyAnimator.getCurrentAnimatorPlayState();
            let time = playState.normalizedTime;
            return time >= 1;
        }
        playWingAnimation(animationId, mixFactor = 0.1, loadEndCallback, playEndCallback) {
            if (!this.parts[PartType.wing])
                return;
            let animator = this.parts[PartType.wing].nodes[0].animator;
            loadEndCallback && loadEndCallback();
            let clip = animator.getControllerLayer(0).getAnimatorState(animationId).clip;
            if (animator.getCurrentAnimatorPlayState(0).animatorState.name == animationId && clip.islooping == true) {
                return;
            }
            this._playerWingAnimationLoaded(animationId, clip, mixFactor, playEndCallback);
        }
        _playerWingAnimationLoaded(animationId, clip, mixFactor, playEndCallback) {
            if (!this.parts[PartType.wing])
                return;
            let animator = this.parts[PartType.wing].nodes[0].animator;
            if (mixFactor == 0) {
                animator.play(animationId, 0, 0);
            }
            else {
                animator.crossFade(animationId, mixFactor);
            }
            if (this.wingBackTimer) {
                this.wingBackTimer.stop();
            }
            if (!clip.islooping) {
                this.wingBackTimer = Timer.callLater(clip.duration(), () => {
                    this.playWingAnimation(ANIMATION_ID.wing_idle);
                    playEndCallback && playEndCallback();
                }, this);
            }
        }
        playFaceAnimation(animationId, mixFactor = 0.1, loadEndCallback, playEndCallback) {
            if (!this.parts[PartType.face])
                return;
            let animationData = mgrCfg.get_from_animation_db(animationId);
            if (!animationData) {
                loadEndCallback && loadEndCallback();
                playEndCallback && playEndCallback();
                return;
            }
            let animator = this.parts[PartType.face].nodes[0].animator;
            let animatorState = animator.getControllerLayer(0).getAnimatorState(animationId);
            if (!animatorState) {
                Laya.AnimationClip.load(animationData.path, new Laya.Handler(this, (clip) => {
                    let __temp = this.baseBodyAnimator.getControllerLayer(0).getAnimatorState(animationId);
                    if (__temp)
                        return;
                    animatorState = new Laya.AnimatorState();
                    animatorState.clip = clip;
                    animatorState.clipStart = 0;
                    animatorState.clipEnd = 1;
                    animatorState.name = animationId;
                    animator.getControllerLayer(0).addState(animatorState);
                    animator.crossFade(animationId, 0.1);
                    loadEndCallback && loadEndCallback();
                    this._playerFaceAnimationLoaded(animationId, clip, mixFactor, playEndCallback);
                }));
            }
            else {
                animator.crossFade(animationId, 0.1);
                loadEndCallback && loadEndCallback();
                let clip = animator.getControllerLayer(0).getAnimatorState(animationId).clip;
                if (animator.getCurrentAnimatorPlayState(0).animatorState.name == animationId && clip.islooping == true) {
                    return;
                }
                this._playerFaceAnimationLoaded(animationId, clip, mixFactor, playEndCallback);
            }
            return;
        }
        _playerFaceAnimationLoaded(animationId, clip, mixFactor, playEndCallback) {
            if (!this.parts[PartType.face])
                return;
            let animator = this.parts[PartType.face].nodes[0].animator;
            if (mixFactor == 0) {
                animator.play(animationId, 0, 0);
            }
            else {
                animator.crossFade(animationId, mixFactor);
            }
            if (this.faceBackTimer) {
                this.faceBackTimer.stop();
            }
            if (!clip.islooping) {
                this.faceBackTimer = Timer.callLater(clip.duration(), () => {
                    this.playFaceAnimation(ANIMATION_ID.face.idle);
                    playEndCallback && playEndCallback();
                }, this);
            }
        }
        playAnimation(animationId, mixFactor = 0.1, loadEndCallback, playEndCallback, bRepeat = true) {
            let animationData = mgrCfg.get_from_animation_db(animationId);
            if (!animationData) {
                loadEndCallback && loadEndCallback();
                playEndCallback && playEndCallback();
                return;
            }
            animationData = mgrCfg.get_from_animation_db(animationId);
            let animatorState = this.baseBodyAnimator.getControllerLayer(0).getAnimatorState(animationId);
            if (!animatorState) {
                Laya.AnimationClip.load(animationData.path, new Laya.Handler(this, (clip) => {
                    let __temp = this.baseBodyAnimator.getControllerLayer(0).getAnimatorState(animationId);
                    if (__temp)
                        return;
                    animatorState = new Laya.AnimatorState();
                    animatorState.clip = clip;
                    animatorState.clipStart = 0;
                    animatorState.clipEnd = 1;
                    animatorState.name = animationId;
                    this.baseBodyAnimator.getControllerLayer(0).addState(animatorState);
                    this._playerAnimationLoaded(animationId, clip, mixFactor, playEndCallback);
                    loadEndCallback && loadEndCallback();
                }));
            }
            else {
                let clip = animatorState.clip;
                if (this.baseBodyAnimator.getCurrentAnimatorPlayState(0).animatorState.name == animationId && (clip.islooping == true || !bRepeat)) {
                    return;
                }
                this._playerAnimationLoaded(animationId, clip, mixFactor, playEndCallback);
                loadEndCallback && loadEndCallback();
            }
        }
        _playerAnimationLoaded(animationId, clip, mixFactor, playEndCallback) {
            if (mixFactor == 0) {
                this.baseBodyAnimator.play(animationId, 0, 0);
            }
            else {
                this.baseBodyAnimator.crossFade(animationId, mixFactor);
            }
            if (this.bodyBackTimer) {
                this.bodyBackTimer.stop();
            }
            if (this.bodySmokeTimer) {
                this.bodySmokeTimer.stop();
            }
            if (!clip.islooping) {
                this.bodyBackTimer = Timer.callLater(clip.duration() / this.timeScale, () => {
                    this.playAnimation(ANIMATION_ID.idle);
                    playEndCallback && playEndCallback();
                }, this);
                let animationIds = ["tiaosheng_play-ts_play01", "tiaosheng_play-ts_play02"];
                if (animationIds.indexOf(animationId) >= 0) {
                    this.bodySmokeTimer = Timer.callLater(clip.duration() * 0.8, () => {
                        mgrLoader.loadModeWithModeId(MODEL_ID.effect.e_tiaosheng_smoke, () => {
                            let smoke = mgrLoader.getModeWithModeId(MODEL_ID.effect.e_tiaosheng_smoke);
                            this.addChild(smoke);
                        }, 0, 1);
                    });
                }
            }
        }
        useCartonMaterial(mode, partId) {
            let partData = mgrCfg.get_from_part_db(partId);
            return mgrMaterial.setCartonShader(mode, partData.modelId);
        }
        reload() {
            let oldPartIds = [];
            for (const k in this.parts) {
                let element = this.parts[k];
                oldPartIds.push(element.partId);
                let nodes = element.nodes;
                for (let index = 0; index < nodes.length; index++) {
                    const node = nodes[index];
                    mgrLoader.Pool.recoverModel(node.node);
                }
            }
            mgrLoader.Pool.recoverModel(this.baseBody);
            this.parts = [];
            this.loadDefault(() => { });
            this.fillByPartIds(oldPartIds);
        }
        clear() {
            if (this.bLoadingPart)
                return;
            let defaultPartIds = [];
            mgrCfg.forDb_from_part_type_db((k, v) => {
                if (v.defaultPartId) {
                    defaultPartIds.push(v.defaultPartId);
                }
            });
            for (const k in this.parts) {
                let element = this.parts[k];
                if (!element)
                    continue;
                if (defaultPartIds.indexOf(element.partId) >= 0) {
                    continue;
                }
                let nodes = element.nodes;
                for (let index = 0; index < nodes.length; index++) {
                    const node = nodes[index];
                    mgrLoader.Pool.recoverModel(node.node);
                }
            }
            this.fillByPartIds(defaultPartIds);
            this.loadPart();
        }
        getPartIds(bAll = false) {
            let partIds = [];
            bAll && partIds.push(-1);
            bAll && partIds.push(-2);
            for (const k in this.parts) {
                let element = this.parts[k];
                if (element) {
                    let partData = mgrCfg.get_from_part_db(element.partId);
                    if (this.unloadedPartIds[partData.type]) {
                        partIds.push(this.unloadedPartIds[partData.type]);
                    }
                    else {
                        partIds.push(element.partId);
                    }
                }
            }
            return partIds;
        }
        linkMode2RHand(model) {
            this.linkModel(model, "Guadian_RHand");
        }
        linkMode2LHand(model) {
            this.linkModel(model, "Guadian_LHand");
        }
        linkModel(model, linkPointName) {
            if (!model || model.destroyed)
                return;
            if (this.linkedModels.indexOf(model) >= 0) {
                this.unlinkModel(model);
            }
            this.linkedModels.push(model);
            Tools.link2Node(linkPointName, this.baseBody, model);
        }
        unlinkModel(model) {
            if (!model)
                return;
            let index = this.linkedModels.indexOf(model);
            if (index == -1)
                return;
            this.linkedModels.splice(index, 1);
            mgrLoader.Pool.recoverModel(model);
        }
        hideWings() {
            let nodes = this.parts[PartType.wing].nodes;
            for (let i = 0; i < nodes.length; i++) {
                const nodeInfo = nodes[i];
                nodeInfo.node.active = false;
            }
        }
        showWings() {
            let nodes = this.parts[PartType.wing].nodes;
            for (let i = 0; i < nodes.length; i++) {
                const nodeInfo = nodes[i];
                nodeInfo.node.active = true;
            }
        }
        get wingScale() {
            return this.__wingScale;
        }
        set wingScale(value) {
            this.__wingScale = value;
            if (!this.parts[PartType.wing])
                return;
            let nodes = this.parts[PartType.wing].nodes;
            for (let i = 0; i < nodes.length; i++) {
                const nodeInfo = nodes[i];
                nodeInfo.node.transform.localScale = new Laya.Vector3(value, value, value);
            }
        }
        get wingOffset() {
            return this.__wingOffset;
        }
        set wingOffset(value) {
            this.__wingOffset = value;
            if (!this.parts[PartType.wing])
                return;
            let nodes = this.parts[PartType.wing].nodes;
            for (let i = 0; i < nodes.length; i++) {
                const nodeInfo = nodes[i];
                nodeInfo.node.transform.localPositionY = value;
            }
        }
        hideShadow() {
            this.shadow.active = false;
        }
        showShadow() {
            this.shadow.active = true;
        }
        pause() {
            this.baseBodyAnimator.speed = 0;
        }
        resume() {
            this.baseBodyAnimator.speed = 1;
        }
        set timeScale(value) {
            this.baseBodyAnimator.speed = value;
        }
        get timeScale() {
            return this.baseBodyAnimator.speed;
        }
        set randomDiscardFactor(value) {
            for (const type in this.parts) {
                let part = this.parts[type];
                for (let index = 0; index < part.nodes.length; index++) {
                    const nodeInfo = part.nodes[index];
                    for (let i_m = 0; i_m < nodeInfo.materials.length; i_m++) {
                        const element = nodeInfo.materials[i_m];
                        element.randomDiscardFactor = value;
                    }
                }
            }
            for (let i = 0; i < this.baseBodyMaterials.length; i++) {
                const element = this.baseBodyMaterials[i];
                element.randomDiscardFactor = value;
            }
            for (let i = 0; i < this.shadowMaterials.length; i++) {
                const element = this.shadowMaterials[i];
                element.randomDiscardFactor = value;
            }
        }
        getNodeByType(type) {
            let info = this.parts[type];
            return info.nodes[0].node;
        }
    }

    class mgrPart extends Manager {
        static onLoad() {
            super.onLoad();
            this.loadRecord();
            this.registerListeners({
                MSG_ITEM_AMOUNT_CHANGED: this.onMsgItemAmountChanged.bind(this),
            });
        }
        static loadRecord() {
            super.loadRecord();
            let record = mgrRecord.getData("mgr_part") || {};
            this.mainPartIds = record.mainPartIds || [];
            this.stagePartIds = record.stagePartIds || [];
            this.getedRewardSuitIds = record.getedRewardSuitIds || [];
            this.newPartIds = record.newPartIds || [];
        }
        static saveRecord() {
            super.saveRecord();
            let record = {
                mainPartIds: this.mainPartIds,
                stagePartIds: this.stagePartIds,
                getedRewardSuitIds: this.getedRewardSuitIds,
                newPartIds: this.newPartIds,
            };
            mgrRecord.setData("mgr_part", record);
        }
        static getRecommendTagsByPartId(partId) {
            let datas = [];
            let partData = mgrCfg.get_from_part_db(partId);
            let scores = [partData.score1, partData.score2, partData.score3, partData.score4, partData.score5,
                partData.score6, partData.score7, partData.score8, partData.score9, partData.score10];
            for (let i = 0; i < scores.length; i++) {
                const score = scores[i];
                let tagData = mgrCfg.get_from_part_tag_db(i + 1);
                datas.push({
                    index: i,
                    id: tagData.id,
                    score: score,
                    icon: tagData.icon,
                });
            }
            datas = Tools.sortArrayByField(datas, "-score");
            return [datas[0], datas[1]];
        }
        static getMaxPartNum() {
            return ul.length(mgrCfg.getDb("part_db"));
        }
        static getOwnPartNum() {
            let count = 0;
            mgrCfg.forDb_from_part_db((k, v) => {
                if (mgrPlayer.getItemAmount(v.id) > 0) {
                    count++;
                }
            });
            return count;
        }
        static getLastClothes() {
            return this.mainPartIds;
        }
        static setLastClothes(partIds) {
            this.mainPartIds = partIds;
            this.saveRecord();
        }
        static isSuitRewardGeted(suitId) {
            return this.getedRewardSuitIds.indexOf(suitId) >= 0;
        }
        static obtainSuitReward(suitId) {
            if (this.isSuitRewardGeted(suitId)) {
                mgrTip.showMsgTip("已领取");
                return false;
            }
            let suitData = mgrCfg.get_from_suit_db(suitId);
            let haveCount = 0;
            let maxCount = 0;
            for (let index = 0; index < suitData.partIds.length; index++) {
                const partId = suitData.partIds[index];
                if (mgrPlayer.getItemAmount(partId) > 0)
                    haveCount++;
                maxCount++;
            }
            if (haveCount < maxCount) {
                mgrTip.showMsgTip("还没有收集完毕, 点击卡片查看详情");
                return false;
            }
            this.getedRewardSuitIds.push(suitId);
            for (let index = 0; index < suitData.collectionRewards.length; index++) {
                const element = suitData.collectionRewards[index];
                mgrPlayer.addItemAmount(element[0], element[1], "领取图鉴奖励");
                mgrTip.addGotItemTip(element[0], element[1], null, {
                    fOnClose: () => {
                    }
                });
            }
            this.saveRecord();
            return true;
        }
        static getBadgeCount() {
            let bCan = false;
            mgrCfg.forDb_from_suit_db((k, v) => {
                let bAllHave = true;
                for (let i = 0; i < v.partIds.length; i++) {
                    const partId = v.partIds[i];
                    if (mgrPlayer.getItemAmount(partId) <= 0) {
                        bAllHave = false;
                        break;
                    }
                }
                if (bAllHave && !this.isSuitRewardGeted(v.id)) {
                    bCan = true;
                    return true;
                }
            });
            if (bCan)
                return 1;
            return 0;
        }
        static getSuitProgress(suitId) {
            let suitData = mgrCfg.get_from_suit_db(suitId);
            let max = 0;
            let cur = 0;
            for (let i = 0; i < suitData.partIds.length; i++) {
                const partId = suitData.partIds[i];
                max++;
                if (mgrPlayer.getItemAmount(partId) > 0)
                    cur++;
            }
            return [cur, max];
        }
        static getSuitDatas() {
            let datas = [];
            mgrCfg.forDb_from_suit_db((k, v) => {
                datas.push(v);
                let [cur, max] = this.getSuitProgress(v.id);
                if (cur >= max) {
                    v[`__order`] = -1;
                }
                else {
                    v[`__order`] = v.id;
                }
            });
            datas = Tools.sortArrayByField(datas, "__order");
            return datas;
        }
        static getBadgeCountByCategory(category) {
            let bCan = false;
            mgrCfg.forDb_from_suit_db((k, v) => {
                if (v.type == category) {
                    let bAllHave = true;
                    for (let i = 0; i < v.partIds.length; i++) {
                        const partId = v.partIds[i];
                        if (mgrPlayer.getItemAmount(partId) <= 0) {
                            bAllHave = false;
                            break;
                        }
                    }
                    if (bAllHave && !this.isSuitRewardGeted(v.id)) {
                        bCan = true;
                        return true;
                    }
                }
            });
            if (bCan)
                return 1;
            return 0;
        }
        static _getRandomPartIdByPartType(partType) {
            let ids = [];
            let db = mgrCfg.getDb("part_db");
            for (let k in db) {
                let v = db[k];
                if (v.type == partType && !v.bIgnoreInGrade) {
                    ids.push(v.id);
                }
            }
            if (ids.length <= 0) {
                return 0;
            }
            return ids[Tools.random(ids.length - 1)];
        }
        static _debugFillRandom() {
            let partIds = [];
            let partTypes = [
                PartType.hair, PartType.cloth, PartType.face, PartType.shoe, PartType.sock, PartType.wing
            ];
            for (let k in partTypes) {
                let partType = partTypes[k];
                let partId = this._getRandomPartIdByPartType(partType);
                if (partId != 0) {
                    partIds.push(partId);
                }
            }
            return partIds;
        }
        static calcWeight(partIds) {
            let total = 0;
            for (let k in partIds) {
                let partId = partIds[k];
                let template = mgrCfg.get_from_part_db(partId);
                if (!template) {
                    continue;
                }
                total += (template.level || 0);
            }
            return total;
        }
        static onMsgItemAmountChanged(e) {
            let itemId = e.itemId;
            if (!!mgrCfg.get_from_part_db(itemId) && mgrPlayer.getItemAmount(itemId) == 1) {
                this.newPartIds.push(itemId);
            }
        }
        static deleteNewPart(partId) {
            let index = this.newPartIds.indexOf(partId);
            if (index == -1)
                return;
            this.newPartIds.splice(index, 1);
        }
        static isNewPart(partId) {
            return this.newPartIds.indexOf(partId) >= 0;
        }
        static isNewType(type) {
            for (let i = 0; i < this.newPartIds.length; i++) {
                const partId = this.newPartIds[i];
                let partData = mgrCfg.get_from_part_db(partId);
                if (partData.type == type)
                    return true;
            }
            return false;
        }
        static getPartBadgeCount() {
            return this.newPartIds.length;
        }
        static getAllLoadedPartIds() {
            let partIds = {};
            mgrCfg.forDb_from_part_db((k, v) => {
                if (!partIds[v.type])
                    partIds[v.type] = { hash: {}, array: [] };
                let b = mgrLoader.isLoadedWithModelId(v.modelId);
                partIds[v.type].hash[v.id] = b;
                b && partIds[v.type].array.push(v.id);
            });
            return partIds;
        }
    }

    class Layout {
        static widget(h, v, node, anchor = { x: 0, y: 0 }, parent = Laya.stage) {
            if (parent == Laya.stage) {
                if (Laya.stage.height > 1152) {
                    let delta = Laya.stage.height - 1152;
                    let minV = delta / 2;
                    let maxV = Laya.stage.height - minV;
                    if (v >= 0 && v <= 1) {
                        v = ul.clamp(v, minV / Laya.stage.height, maxV / Laya.stage.height);
                    }
                    else if (v > 1) {
                        if (v < 300) {
                            v = ul.clamp(v + minV, minV, maxV);
                        }
                        else if (v > Laya.stage.width - 300) {
                            v = ul.clamp(v - minV, minV, maxV);
                        }
                        else {
                            v = ul.clamp(v, minV, maxV);
                        }
                    }
                }
            }
            let absh = Math.abs(h);
            let absv = Math.abs(v);
            let x = parent.width * h;
            let y = parent.height * v;
            if (absh > 1)
                x = h;
            if (absv > 1)
                y = v;
            if (node[`anchorX`] == null || isNaN(node[`anchorX`])) {
                node[`anchorX`] = node.pivotX / node.width;
            }
            if (node[`anchorY`] == null || isNaN(node[`anchorY`])) {
                node[`anchorY`] = node.pivotY / node.height;
            }
            x += node[`anchorX`] * node.width - anchor.x * node.width;
            y += node[`anchorY`] * node.height - anchor.y * node.height;
            let wPos = parent.localToGlobal(new Laya.Point(x, y));
            let nplPos = node.parent.globalToLocal(new Laya.Point(wPos.x, wPos.y));
            if (h == -1)
                nplPos.x = node.x;
            if (v == -1)
                nplPos.y = node.y;
            node.pos(nplPos.x, nplPos.y, true);
        }
    }

    class vRoleLevelUpDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vRoleLevelUpDialog";
            this.exportNodeNames = [
                "CC_spriteBg",
                "CC_boxList",
                "CC_boxLevel",
                "CC_spriteLight",
                "CC_labelLevel",
                "CC_buttonClose",
                "CC_buttonGet",
                "CC_buttonStartAd",
                "CC_spriteAdIcon",
                "CC_labelAdWish",
                "CC_buttonVideoShare",
                "CC_boxLayoutShareConsume",
                "CC_labelShareTip",
            ];
            vRoleLevelUpDialog.instance = this;
        }
        onOpened() {
            super.onOpened();
            this.buttonStartAd.fOnClick = this.onTouchButtonStartAd.bind(this);
            this.buttonGet.fOnClick = this.onTouchButtonGet.bind(this);
            this.buttonClose.fOnClick = this.onTouchButtonClose.bind(this);
            let bTriggerAd = mgrAd.preCheckCanTriggerAdEvent(AD_EVENT_ID.VIDEO.double_level_up);
            this.buttonStartAd.__node.visible = bTriggerAd;
            this.buttonClose.__node.visible = bTriggerAd;
            this.buttonVideoShare.__node.visible = mgrChannel.canUseVideoRecord() && !mgrGuide.isGuiding();
            this.buttonVideoShare.fOnClick = this.onTouchButtonVideoShare.bind(this);
            let count = mgrChannel.getRecordRewardAmount();
            this.labelShareTip.text = `成功分享, 可获得:${count}`;
            this.boxLayoutShareConsume.visible = count > 0;
            mgrLoader.loadFont("levelUp", this.labelLevel);
            this.fadeIn();
            mgrSound.play(6);
            mgrSound.pauseEffect("vRoleLevelUpDialog");
            this.registerListeners({
                MSG_AD_EVENT_SUCCESSD: this.onMsgAdEventSuccessed.bind(this),
            });
            mgrChannel.canUseVideoRecord() && mgrSdk.recordGameVideo("start");
            this.context.startTime = Tools.time();
        }
        onClosed() {
            super.onClosed();
            vRoleLevelUpDialog.instance = null;
            mgrSound.resumeEffect("vRoleLevelUpDialog");
        }
        getPreLoadModelIds() {
            return [MODEL_ID.effect.shengji_flare];
        }
        getPreLoadAnimationIds() {
            return [ANIMATION_ID.shengji, ANIMATION_ID.face.shengji];
        }
        fadeIn() {
            this.spriteBg.alpha = 0;
            this.spriteBg.zOrder = -3;
            this.boxLevel.zOrder = -2;
            Layout.widget(10, 10, this.buttonClose.__node);
            this.spriteLight.scale(0, 0);
            this.boxList.alpha = 0;
            this.buttonGet.__node.scale(0, 0);
            this.buttonStartAd.__node.scale(0, 0);
            this.buttonVideoShare.__node.scale(0, 0);
            this.buttonClose.__node.scale(0, 0);
            let level = this.context.level || mgrInteraction.level;
            this.labelLevel.text = `${level - 1}`;
            this.labelLevel.scale(0, 0);
            CustomTween.to(this.spriteBg, { alpha: 1 }, 300)
                .callback(() => {
                this.levelAction();
            })
                .start(1);
        }
        levelAction() {
            let level = this.context.level || mgrInteraction.level;
            let spine = ULSkeleton.create("ui_shengji", () => {
                Timer.callLater(0.016, () => {
                    this.boxLevel.addChild(spine);
                    spine.pos(this.boxLevel.width / 2, this.boxLevel.height / 2);
                    spine.playAnimation("idle1", false);
                    this.labelLevel.zOrder = 1000;
                    CustomTween.to(this.labelLevel, { scaleX: 1.2, scaleY: 1.2 }, 5 / 30 * 1000)
                        .to({ scaleX: 0.8, scaleY: 0.8 }, 5 / 30 * 1000)
                        .to({ scaleX: 1, scaleY: 1 }, 5 / 30 * 1000)
                        .to({ scaleX: 1, scaleY: 1 }, 10 / 30 * 1000)
                        .callback(() => {
                        this.add3DEffectAtFront(MODEL_ID.effect.shengji_flare, this.boxLevel, 3);
                    })
                        .to({ scaleX: 0.5, scaleY: 0.5 }, 5 / 30 * 1000)
                        .callback(() => {
                        this.labelLevel.text = `${level}`;
                    })
                        .to({ scaleX: 1.2, scaleY: 1.2 }, 5 / 30 * 1000)
                        .to({ scaleX: 0.8, scaleY: 0.8 }, 5 / 30 * 1000)
                        .to({ scaleX: 1, scaleY: 1 }, 5 / 30 * 1000)
                        .delayTime(300)
                        .callback(() => {
                        CustomTween.to(this.spriteLight, { scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                            .callback(() => {
                            CustomTween.rotateForever(this.spriteLight, 10000);
                        })
                            .start(1);
                        this.levelJumpAction();
                    })
                        .start(1);
                }, this);
            });
        }
        levelJumpAction() {
            let x = (this.width - mgrDirector.width) / 2 + this.boxLevel.width / 2 + 20;
            let y = 255;
            let wPos = this.localToGlobal(new Laya.Point(x, y));
            CustomTween.jumpTo(this.boxLevel, wPos, 0.5, 500, () => {
                this.roleShowAction();
            });
        }
        roleShowAction() {
            let avatar = new RoleAvatar;
            avatar.fillByPartIds(mgrPart.getLastClothes());
            this.add3DEffectAtBack(avatar, 0);
            avatar.transform.scale = new Laya.Vector3;
            !mgrGuide.isGuiding() && (avatar.timeScale = 0.6);
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_zhoubisai_show, this, 3);
            avatar.registerLoadEndCallback(() => {
                avatar.playWingAnimation(ANIMATION_ID.wing_fly);
                avatar.playFaceAnimation(ANIMATION_ID.face.kaixin01);
                avatar.playAnimation(ANIMATION_ID.PVP.COME, 0, () => {
                    avatar.transform.scale = new Laya.Vector3(1, 1, 1);
                    this.cameraBack.fieldOfView = 25;
                    this.cameraBack.getComponent(CameraFollow).distance = new Laya.Vector3(0, 1.25, 7);
                    this.cameraBack.getComponent(CameraFollow).endRotation = new Laya.Vector3(-6, 0, 0);
                    this.cameraBack.transform.position = new Laya.Vector3(0, 1.25, 7);
                    this.cameraBack.transform.rotationEuler = new Laya.Vector3(-6, 0, 0);
                }, () => {
                    !mgrGuide.isGuiding() && (avatar.timeScale = 0.85);
                    avatar.playFaceAnimation(ANIMATION_ID.face.shengji);
                    avatar.playAnimation(ANIMATION_ID.shengji, 0.1, () => {
                    }, () => {
                        this.cameraBack.getComponent(CameraFollow).distance = new Laya.Vector3(0, 1.25, 8.80);
                        Timer.callLater(0.5, () => {
                            this.showRewardAction();
                        }, this);
                    });
                });
            });
        }
        showRewardAction() {
            let level = this.context.level || mgrInteraction.level;
            this.boxList.alpha = 1;
            let oldLevelData = mgrCfg.get_from_role_level_db(level - 1);
            let rewards = oldLevelData.rewards;
            mgrSound.play(107);
            for (let i = 0; i < rewards.length; i++) {
                const [itemId, amount] = rewards[i];
                let item = new vRoleLevelUpRewardItem({});
                item.fillByData({
                    itemId: itemId,
                    amount: amount,
                });
                this.boxList.addChild(item);
                item.y = this.boxList.height / 2;
                item.scale(0, 0);
                CustomTween.delayTime(item, i * 500)
                    .to({ scaleX: 1, scaleY: 1 }, 500, Laya.Ease.backOut)
                    .start(1);
            }
            this.buttonGet.__node.visible && CustomTween.delayTime(this.buttonGet.__node, 1500)
                .callback(() => {
                mgrGuide.registerGuideNode(`vLevelUpDialog.buttonGet`, this.buttonGet.__node);
            })
                .to({ scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                .delayTime(500)
                .callback(() => {
                mgrChannel.canUseVideoRecord() && mgrSdk.recordGameVideo("stop");
                console.log(`recordVideo duration:${Tools.time() - this.context.startTime}`);
                CustomTween.to(this.buttonVideoShare.__node, { scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                    .start(1);
            })
                .start(1);
            this.buttonStartAd.__node.visible && CustomTween.delayTime(this.buttonStartAd.__node, 1500)
                .to({ scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                .delayTime(500)
                .start(1);
            CustomTween.delayTime(this.buttonClose.__node, 1500)
                .to({ scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                .callback(() => {
            })
                .start(1);
        }
        onTouchButtonStartAd() {
            mgrAd.triggerAdEvent(AD_EVENT_ID.VIDEO.double_level_up, null, true);
        }
        onTouchButtonGet() {
            this.closeDialog();
            mgrInteraction.obtainLevelUpReward(mgrInteraction.level != 2);
            this.cameraBack.getComponent(CameraFollow).distance = new Laya.Vector3(0, 0, 88888.80);
            this.sendMsg("MSG_GUIDE_EVENT", { id: `vLevelUpDialog.clickButtonGet` });
            if (mgrInteraction.restState == E_REST_STATE.rest) {
                mgrSound.play(7);
            }
            else {
                mgrSound.play(1);
            }
        }
        onTouchButtonClose() {
            this.onTouchButtonGet();
        }
        onTouchButtonVideoShare() {
            mgrSdk.shareGameVideo();
            this.boxLayoutShareConsume.visible = false;
            this.buttonVideoShare.__node.visible = false;
        }
        onMsgAdEventSuccessed(e) {
            if (e.adEventId == AD_EVENT_ID.VIDEO.double_level_up) {
                this.closeDialog();
                mgrInteraction.obtainLevelUpReward(mgrInteraction.level != 2, 2);
                this.cameraBack.getComponent(CameraFollow).distance = new Laya.Vector3(0, 0, 88888.80);
                this.sendMsg("MSG_GUIDE_EVENT", { id: `vLevelUpDialog.clickButtonGet` });
                if (mgrInteraction.restState == E_REST_STATE.rest) {
                    mgrSound.play(7);
                }
                else {
                    mgrSound.play(1);
                }
            }
        }
    }

    class mgrShop extends Manager {
        static onLoad() {
            super.onLoad();
            this.loadRecord();
            this.init();
            this.registerListeners({
                MSG_SDK_PAY_RESULT: this.onMsgSdkPayResult,
                MSG_SDK_PRE_PAY_RESULT: this.onMsgSdkPrePayResult,
            });
        }
        static loadRecord() {
            super.loadRecord();
            let record = mgrRecord.getData("mgrShop") || {};
            this.todayDiscounShopIds = record.todayDiscounShopIds || [];
            this.lastRereshDiscountTime == record.lastRereshDiscountTime || 0;
        }
        static saveRecord() {
            super.saveRecord();
            let record = {
                todayDiscounShopIds: this.todayDiscounShopIds,
                lastRereshDiscountTime: this.lastRereshDiscountTime,
            };
            mgrRecord.setData("mgrShop", record);
        }
        static init() {
            if (!Tools.isOneDay(this.lastRereshDiscountTime, Tools.time())) {
                this.lastRereshDiscountTime = Tools.time();
                let shops = this.getAllShopItemListByCategory([2]);
                let index1 = Tools.random(0, Math.floor(shops.length / 2));
                let index2 = Tools.random(Math.floor(shops.length / 2) + 1, shops.length - 1);
                this.todayDiscounShopIds = [];
                this.todayDiscounShopIds.push(shops[index1].id);
                this.todayDiscounShopIds.push(shops[index2].id);
            }
        }
        static isDiscount(shopId) {
            return this.todayDiscounShopIds.indexOf(shopId) >= 0;
        }
        static getAllShopItemListByCategory(categorys) {
            if (!categorys)
                return [];
            let hash = {};
            for (let i = 0; i < categorys.length; i++) {
                const category = categorys[i];
                hash[category] = true;
            }
            let arr = [];
            mgrCfg.forDb_from_shop_template_db((k, v) => {
                if (hash[v.category]
                    && mgrAlu.check(v.aluId)) {
                    let bDiscount = this.isDiscount(v.id);
                    if (bDiscount) {
                        v[`_discount`] = -1;
                    }
                    else {
                        v[`_discount`] = 1;
                    }
                    let itemId = v.items[0][0];
                    let bPart = !!mgrCfg.get_from_part_db(itemId);
                    let bHaved = mgrPlayer.getItemAmount(itemId) > 0;
                    if (bPart && bHaved) {
                        v[`_haved`] = 1;
                    }
                    else {
                        v[`_haved`] = -1;
                    }
                    arr.push(v);
                }
            });
            arr = Tools.sortArrayByField(arr, ["_haved", "_discount", "-order", "id"]);
            return arr;
        }
        static requestBuy(shopId, bIgnoreConsume = false) {
            let shopData = mgrCfg.get_from_shop_template_db(shopId);
            if (!shopData) {
                return false;
            }
            if (bIgnoreConsume) {
                this.responseBuy(shopId);
                return true;
            }
            let bDiscount = this.isDiscount(shopId);
            let price = shopData.price;
            if (bDiscount) {
                price = Math.floor(shopData.price / 2);
            }
            let priceUnit = shopData.priceUnit;
            if (priceUnit == 0) {
                mgrSdk.openPay(shopData.payId);
                return false;
            }
            let itemData = mgrCfg.get_from_item_template_db(priceUnit);
            if (!itemData) {
                return false;
            }
            if (mgrPlayer.getItemAmount(priceUnit) < price) {
                this.tipItemNotEnough(priceUnit);
                this.tryOpenShop(priceUnit);
                return false;
            }
            else {
                mgrPlayer.addItemAmount(priceUnit, -price, "购买消耗");
                this.responseBuy(shopId);
                return true;
            }
        }
        static responseBuy(shopId) {
            let shopData = mgrCfg.get_from_shop_template_db(shopId);
            if (!shopData) {
                return;
            }
            for (let index = 0; index < shopData.items.length; index++) {
                const [itemId, count, bIgnoreGotTip] = shopData.items[index];
                mgrPlayer.addItemAmount(itemId, count, "购买");
                if (!bIgnoreGotTip) {
                    mgrTip.addGotItemTip(itemId, count, null, null);
                }
            }
            this.sendMsg("MSG_SHOP_BUY_SUCCESSED", { shopId: shopId });
            mgrSdk.statisOnItemBought(shopId, 1, "购买");
            shopData.statisPoint && mgrSdk.staticPointEvent(shopData.statisPoint);
        }
        static getShopIdByPayId(payId) {
            let shopId;
            mgrCfg.forDb_from_shop_template_db((key, value) => {
                if (value.payId == payId) {
                    shopId = value.id;
                    return true;
                }
            });
            return shopId;
        }
        static tryConsumeItem(itemId, amount, reason) {
            let haveAmount = mgrPlayer.getItemAmount(itemId);
            if (haveAmount < amount) {
                this.tipItemNotEnough(itemId);
                return false;
            }
            mgrPlayer.addItemAmount(itemId, -amount, reason);
            return true;
        }
        static tipItemNotEnough(itemId = Const.ITEM_ID_GOLD) {
            let itemData = mgrCfg.get_from_item_template_db(itemId);
            if (!itemData) {
                return;
            }
            mgrTip.showItemTip(itemId, 1, ul.format("%s不足", itemData.name));
            if (itemId == Const.ITEM_ID_GOLD) {
                if (mgrAd.preCheckCanTriggerAdEvent("free_gold")) {
                    mgrDirector.openDialog(`vLuckGoldDialog`);
                }
            }
            else if (itemId == Const.ITEM_ID_GARDEN_WATER) {
                mgrDirector.openDialog(`vGetItemWatchAdDialog`, {
                    itemId: Const.ITEM_ID_GARDEN_WATER,
                    adEventId: `free_water`
                });
            }
            else if (itemId == Const.ITEM_ID_GARDEN_FERTILIZER) {
                mgrDirector.openDialog(`vGetItemWatchAdDialog`, {
                    itemId: Const.ITEM_ID_GARDEN_FERTILIZER,
                    adEventId: `free_fertilizer`
                });
            }
        }
        static tryOpenShop(itemId = Const.ITEM_ID_GOLD) {
            if (mgrChannel.isOpenPay()) {
            }
        }
        static canSupplyItem(itemId = Const.ITEM_ID_GOLD) {
            if (itemId == Const.ITEM_ID_GOLD && mgrAd.preCheckAdNoCd("free_gold")) {
                return true;
            }
            if (itemId == Const.ITEM_ID_ENERGY && mgrAd.preCheckAdNoCd("free_energy")) {
                return true;
            }
            return false;
        }
        static goWidthRouterId(routerId, param = 0) {
            switch (routerId) {
                case 1:
                    mgrDirector.openDialog("vShopDialog");
                    break;
                case 2:
                    mgrDirector.open2DScene("vStageScene");
                    break;
                case 3:
                    mgrDirector.openDialog(`vSignDialog`);
                    break;
                case 4:
                    mgrDirector.open2DScene("vWishPoolMianScene");
                    break;
                case 5:
                    mgrDirector.open2DScene(`vGardenMainScene`);
                    break;
                default:
                    console.error(`未知跳转类型： ${routerId}`);
                    break;
            }
        }
        static setSdkPayInfo(payInfo) {
            Tools.forEachMap(payInfo, (k, v) => {
                this.sdkPayInfo[v.payCode] = {
                    payCode: v.payCode,
                    price: v.price,
                    proName: v.proName,
                };
            });
        }
        static onMsgSdkPayResult(data) {
            if (data.bSuccessful) {
                let shopId = this.getShopIdByPayId(data.payId);
                this.responseBuy(shopId);
            }
        }
        static onMsgSdkPrePayResult(data) {
            if (data.bSuccessful) {
                mgrTip.showMsgTip("补发订单...");
                let shopId = this.getShopIdByPayId(data.payId);
                this.responseBuy(shopId);
            }
        }
    }
    mgrShop.sdkPayInfo = {};

    class NetworkTask {
        constructor() {
            this.fOnRequest = null;
            this.fOnFaild = null;
            this.fOnReceive = null;
            this.faildMsg = "";
            this.responseData = null;
            this.requestData = {};
            this.retryCount = 0;
        }
        setBackgroundEnabled(value) {
            this.bBackgroundEnabled = value;
            return this;
        }
        isBackgroundEnabled() {
            return this.bBackgroundEnabled;
        }
        setRequestData(value) {
            this.requestData = value;
            return this;
        }
        getRequestData() {
            return this.requestData;
        }
        setResponseData(value) {
            this.responseData = value;
            return this;
        }
        getResponseData() {
            return this.responseData;
        }
        setFaildMsg(value) {
            this.faildMsg = value;
            return this;
        }
        getFaildMsg() {
            return this.faildMsg;
        }
        setOnRequestCallback(value) {
            this.fOnRequest = value;
            return this;
        }
        setOnReceiveCallback(value) {
            this.fOnReceive = value;
            return this;
        }
        setOnFaildCallback(value) {
            this.fOnFaild = value;
            return this;
        }
        triggerRequestCallback() {
            if (this.fOnRequest) {
                this.fOnRequest(this);
            }
        }
        triggerResponseCallback() {
            if (this.fOnReceive) {
                this.fOnReceive(this);
            }
        }
        triggerFaildCallback() {
            if (this.fOnFaild) {
                this.fOnFaild(this);
            }
        }
    }

    class FSMObject {
        constructor() {
            this.curState = -1;
            this.nextState = this.curState;
            this.lastState = this.curState;
            this.stateMap = {};
        }
        registerState(state, enter, execute, leave) {
            if (enter || execute || leave) {
                this.stateMap[state] = {
                    enter: enter,
                    execute: execute,
                    leave: leave,
                };
            }
        }
        setNextState(state) {
            this.nextState = state;
        }
        update() {
            let curStateInvokeInfo = this.stateMap[this.curState];
            let nextStateInvokeInfo = this.stateMap[this.nextState];
            if (this.nextState != this.curState) {
                this.lastState = this.curState;
                this.curState = this.nextState;
                if (curStateInvokeInfo) {
                    if (curStateInvokeInfo.leave)
                        curStateInvokeInfo.leave();
                }
                if (nextStateInvokeInfo) {
                    if (nextStateInvokeInfo.enter)
                        nextStateInvokeInfo.enter();
                }
            }
            if (nextStateInvokeInfo && nextStateInvokeInfo.execute)
                nextStateInvokeInfo.execute();
        }
        getCurState() {
            return this.curState;
        }
        clear() {
            this.curState = -1;
            this.lastState = -1;
            this.nextState = -1;
        }
        getNextState() {
            return this.nextState;
        }
        getLastState() {
            return this.lastState;
        }
    }

    const ST_STANDBY = 1;
    const ST_REQUEST = 2;
    const ST_RESPONSE = 3;
    const ST_FAILD = 4;
    const DEBUG = false;
    class NetworkManager extends FSMObject {
        constructor(adapter) {
            super();
            this.bAutoDoNextTask = true;
            this.currTask = null;
            this.tasks = [];
            this.adapter = null;
            this.adapter = adapter;
            adapter.setReceiveCallback(this.onReceive.bind(this));
            adapter.setFaildCallback(this.onFaild.bind(this));
            this.registerState(ST_STANDBY, this.onEnterStandby.bind(this), this.onExecuteStandby.bind(this), null);
            this.registerState(ST_REQUEST, this.onEnterRequest.bind(this), this.onExecuteRequest.bind(this), null);
            this.registerState(ST_RESPONSE, this.onEnterResponse.bind(this), this.onExecuteResponse.bind(this), null);
            this.registerState(ST_FAILD, this.onEnterFailed.bind(this), this.onExecuteFailed.bind(this), null);
            this.setNextState(ST_STANDBY);
        }
        setAutoDoNextTaskEnabled(value) {
            this.bAutoDoNextTask = value;
        }
        update() {
            super.update();
            this.adapter.update();
        }
        onEnterStandby() {
            if (DEBUG) {
                console.log("onEnterStandby");
            }
            ;
        }
        onExecuteStandby() {
            if (DEBUG) {
                console.log("onExecuteStandby");
            }
            ;
            let tasks = this.tasks;
            if (tasks.length > 0) {
                this.currTask = tasks.shift();
                this.setNextState(ST_REQUEST);
            }
        }
        onEnterRequest() {
            if (DEBUG) {
                console.log("onEnterRequest");
            }
            ;
            let task = this.currTask;
            task.triggerRequestCallback();
            this.adapter.send(task.getRequestData());
        }
        onExecuteRequest() {
        }
        onEnterResponse() {
            if (DEBUG) {
                console.log("onEnterResponse");
            }
            ;
            let task = this.currTask;
            if (!task) {
                return;
            }
            task.triggerResponseCallback();
        }
        onExecuteResponse() {
            if (this.bAutoDoNextTask) {
                this.doNextTask();
            }
        }
        onEnterFailed() {
            if (DEBUG) {
                console.log("onEnterFaild");
            }
            let task = this.currTask;
            if (!task) {
                return;
            }
            task.retryCount++;
            task.triggerFaildCallback();
        }
        onExecuteFailed() {
            if (this.bAutoDoNextTask) {
                this.doNextTask();
            }
        }
        onReceive(responseData) {
            if (this.getCurState() != ST_REQUEST) {
                console.log("[warn] NetworkManager.onReceive, state is !ST_REQUEST!");
                return;
            }
            let task = this.currTask;
            if (!task) {
                console.log("[warn] NetworkManager.onReceive, currTask !found!");
                return;
            }
            task.setResponseData(responseData);
            this.setNextState(ST_RESPONSE);
        }
        onFaild(faildMsg) {
            if (this.getCurState() != ST_REQUEST) {
                console.log("[warn] NetworkManager.onReceive, state is !ST_REQUEST!");
                return;
            }
            let task = this.currTask;
            if (!task) {
                console.log("[warn] NetworkManager.onReceive, currTask !found!");
                return;
            }
            task.setFaildMsg(faildMsg);
            this.setNextState(ST_FAILD);
        }
        addTask(requestData, fOnReceive, fOnFaild, fOnRequest, bBackgroundEnabled) {
            if (!requestData) {
                console.log("[warn] NetworkManager.addTask, requestData is null!");
                return;
            }
            let task = new NetworkTask();
            task.setRequestData(requestData);
            task.setOnReceiveCallback(fOnReceive);
            task.setOnFaildCallback(fOnFaild);
            task.setOnRequestCallback(fOnRequest);
            task.setBackgroundEnabled(bBackgroundEnabled);
            this.tasks.push(task);
        }
        getCurrentTask() {
            return this.currTask;
        }
        getTasks() {
            return this.tasks;
        }
        retryTask(task) {
            this.tasks.push(task);
        }
        stopAllTasks() {
            this.tasks = [];
            this.currTask = null;
            this.adapter.disconnect();
            this.setNextState(ST_STANDBY);
        }
        doNextTask() {
            this.currTask = null;
            this.setNextState(ST_STANDBY);
        }
    }

    class NetworkAdapterBase {
        constructor() {
        }
        setReceiveCallback(callback) {
            this.fOnReceive = callback;
            return this;
        }
        setFaildCallback(callback) {
            this.fOnFaild = callback;
            return this;
        }
        triggerReceiveCallback(responseData) {
            if (this.fOnReceive) {
                this.fOnReceive(responseData);
            }
        }
        triggerFaildCallback(faildMsg) {
            if (this.fOnFaild) {
                this.fOnFaild(faildMsg);
            }
        }
        send(requestData) {
            Timer.callLater(0.1, (timer) => {
                if (requestData.cmd == "CMD_1") {
                    let responseData = {
                        cmd: requestData.cmd,
                        info: "response." + requestData.info,
                    };
                    this.triggerReceiveCallback(responseData);
                }
                else if (requestData.cmd == "CMD_2") {
                    if (Tools.random(100) < 50) {
                        let responseData = {
                            cmd: requestData.cmd,
                            info: "response." + requestData.info,
                        };
                        this.triggerReceiveCallback(responseData);
                    }
                    else {
                        this.triggerFaildCallback("random faild");
                    }
                }
            });
        }
        connect() {
        }
        disconnect() {
        }
        update() {
        }
    }

    class NetworkAdapterHttpUlServer extends NetworkAdapterBase {
        constructor() {
            super(...arguments);
            this.timeout = 3;
        }
        setHost(host) {
            this.host = host;
        }
        setUrlFormat(urlFormat) {
            this.urlFormat = urlFormat;
        }
        setUlServerArg(signkey, platform, appid, channel) {
            this.signkey = signkey;
            this.platform = platform;
            this.appid = appid;
            this.channel = channel;
        }
        setTimeout(timeoutSec) {
            this.timeout = timeoutSec;
        }
        send(requestData) {
            let jsonStr = JSON.stringify(requestData);
            jsonStr = encodeURIComponent(jsonStr);
            let postData = ul.format("signkey=%s&platform=%s&appid=%s&channel=%s&data=%s", this.signkey, this.platform, this.appid, this.channel, jsonStr);
            let url = ul.format(this.urlFormat, this.host);
            console.log("send", url, postData);
            let xhr = new XMLHttpRequest();
            xhr.onreadystatechange = this.onReadyStateChange.bind(this);
            xhr.onerror = this.onError.bind(this),
                xhr.ontimeout = this.onTimeout.bind(this),
                xhr.open("POST", url);
            xhr.timeout = this.timeout * 1000;
            this.xhr = xhr;
            xhr.send(postData);
        }
        onError() {
            console.log("NetworkAdapterHttpUlServer.onError");
            this.triggerFaildCallback(`NetworkAdapterHttpUlServer.onError`);
            this.disconnect();
        }
        onTimeout() {
            console.log("NetworkAdapterHttpUlServer.onTimeout");
            this.triggerFaildCallback(`NetworkAdapterHttpUlServer.onError`);
            this.disconnect();
        }
        onReadyStateChange() {
            let xhr = this.xhr;
            if (!xhr)
                return;
            if (xhr.readyState == 4) {
                if (xhr.status == 200) {
                    let str = xhr.response || "";
                    let reqsponseData = { str: null };
                    let jsonData;
                    try {
                        jsonData = JSON.parse(str);
                    }
                    catch (error) {
                    }
                    if (jsonData) {
                        reqsponseData = jsonData;
                    }
                    else {
                        reqsponseData.str = str;
                    }
                    this.triggerReceiveCallback(reqsponseData);
                }
                else {
                    this.triggerFaildCallback(ul.format("http error: readyState=[%s], status=[%s]", xhr.readyState, xhr.status));
                }
                this.disconnect();
            }
        }
        disconnect() {
            if (!this.xhr) {
                return;
            }
            try {
                this.xhr.abort();
                this.xhr = null;
            }
            catch (error) {
                console.log("disconnect error");
                this.xhr = null;
            }
        }
    }

    class mgrNetwork extends Manager {
        static onLoad() {
            super.onLoad();
            let adapter = new NetworkAdapterHttpUlServer();
            adapter.setHost(Const.SERVER_HOST);
            adapter.setUrlFormat(Const.SERVER_URL_FORMAT);
            adapter.setUlServerArg("ultralisk", "pc", Const.SERVER_APP_ID.toString(), "ultralisk");
            adapter.setTimeout(5);
            this.networkManager = new NetworkManager(adapter);
            Timer.callLoop(1 / 60, this.onTimerSpan.bind(this), true);
        }
        static loadRecord() {
            super.loadRecord();
        }
        static saveRecord() {
            super.saveRecord();
        }
        static onTimerSpan(timer) {
            let dt = timer.span;
            this.networkManager.update();
        }
        static send(cmd, data, bBackgroundEnabled) {
            if (mgrChannel.isChannel4399())
                return;
            if (data == null)
                data = {};
            let requestData = {};
            requestData.cmd = cmd;
            if (data != null) {
                Tools.forEachMap(data, (k, v) => {
                    requestData[k] = v;
                });
            }
            this.networkManager.addTask(requestData, this.onResponse.bind(this), this.onFaild.bind(this), this.onRequest.bind(this), bBackgroundEnabled);
        }
        static onRequest(task) {
            if (!task.isBackgroundEnabled()) {
                this.showWaiting(task);
            }
        }
        static onResponse(task) {
            if (this.networkManager.getTasks().length <= 1) {
                this.hideWaiting();
            }
            this.sendMsg("MSG_NETWORK_RESPONSE", {
                requestData: task.getRequestData(),
                responseData: task.getResponseData(),
            });
        }
        static onFaild(task) {
            this.showFaild();
            Timer.callLater(0.1, () => {
                this.retryTask(task);
            });
        }
        static stopAllTasks() {
            let msgDatas = [];
            let tasks = this.networkManager.getTasks();
            for (let i = 0; i < tasks.length; i++) {
                const task = tasks[i];
                msgDatas.push({ requestData: task.getRequestData() });
            }
            this.networkManager.stopAllTasks();
            this.hideWaiting();
            this.hideFaild();
            for (let i = 0; i < msgDatas.length; i++) {
                const msgData = msgDatas[i];
                this.sendMsg("MSG_NETWORK_STOP_TASK", msgData);
            }
        }
        static retryTask(task) {
            this.networkManager.retryTask(task);
        }
        static showWaiting(task) {
        }
        static hideWaiting() {
        }
        static showFaild() {
        }
        static hideFaild() {
        }
        static tryCheckNetwork(fOnReceive, fOnFaild) {
        }
    }

