                return;
            if (potInfo.seedId == 0)
                return;
            let plantInfo = mgrCfg.get_from_plant_db(potInfo.seedId, potInfo.stageIndex);
            let progress = (Tools.time() - potInfo.stageStartTime) / plantInfo.duration;
            return Math.min(progress, 1);
