            let plantInfo = mgrCfg.get_from_plant_db(potInfo.seedId, potInfo.stageIndex);
            if (plantInfo.operationType != PLANT_OPERATION_TYPE.watering)
                return;
            let consumeCount = plantInfo.operationConsume;
            let haveCount = mgrPlayer.getItemAmount(Const.ITEM_ID_GARDEN_WATER);
            if (consumeCount > haveCount)
                return;
            mgrPlayer.addItemAmount(Const.ITEM_ID_GARDEN_WATER, -consumeCount, "浇水");
            mgrTip.addGotItemTip(Const.ITEM_ID_GARDEN_WATER, -consumeCount);
