            if (!this.hasNextState(potId))
                return;
            let plantInfo = mgrCfg.get_from_plant_db(potInfo.seedId, potInfo.stageIndex);
            if (plantInfo.operationType != PLANT_OPERATION_TYPE.feed)
                return;
            let consumeCount = plantInfo.operationConsume;
            let haveCount = mgrPlayer.getItemAmount(Const.ITEM_ID_GARDEN_FERTILIZER);
            if (consumeCount > haveCount)
                return;
            mgrPlayer.addItemAmount(Const.ITEM_ID_GARDEN_FERTILIZER, -consumeCount, "施肥");
            mgrTip.addGotItemTip(Const.ITEM_ID_GARDEN_FERTILIZER, -consumeCount);
            potInfo.stageStartTime = Tools.time();
            this.saveRecord();
