    class mgrOfflineNearbyRank extends Manager {
        static onLoad() {
            super.onLoad();
            this.loadRecord();
            this.init();
            this.registerListeners({
                MSG_PLAYER_NAME_CHANGED: this.onMsgPlayerNameChanged.bind(this),
            });
        }
        static loadRecord() {
            let record = mgrRecord.getData("mgrOfflineNearbyRank") || {};
            this.players = record.players;
        }
        static saveRecord() {
            let record = {
                players: this.players,
            };
            mgrRecord.setData("mgrOfflineNearbyRank", record);
        }
        static init() {
            if (!this.players) {
                this.players = {};
            }
            let fun = () => {
                let needShowRankIds = [eNearbyRankId.garden, eNearbyRankId.playBall, eNearbyRankId.ropeSkiping, eNearbyRankId.stage, eNearbyRankId.learn];
                for (let i = 0; i < needShowRankIds.length; i++) {
                    const rankId = needShowRankIds[i];
                    if (!this.players[rankId]) {
                        this.players[rankId] = this.randomPlayersForRank(rankId);
                    }
                    else {
                        this.players[rankId] = this.randomChangePlayerForRank(rankId, this.players[rankId]);
                    }
                }
                this.saveRecord();
            };
            fun();
            Timer.callLoop(600, () => {
                fun();
            }, this);
        }
        static randomPlayersForRank(rankId) {
            let maxScore = 0;
            let selfScore = 0;
            if (rankId == eNearbyRankId.garden) {
                maxScore = mgrGarden.getMaxCollectAmount();
                selfScore = mgrGarden.getMyCollectAmount();
            }
            else if (rankId == eNearbyRankId.stage) {
                maxScore = mgrStage.getTotalStageCount();
                selfScore = mgrStage.getStageProgress();
            }
            else if (rankId == eNearbyRankId.ropeSkiping) {
                maxScore = ul.clamp(mgrInteraction.ropeSkippingMaxScore * 1.35, 50, 1000000);
                selfScore = mgrInteraction.ropeSkippingMaxScore;
            }
            else if (rankId == eNearbyRankId.playBall) {
                maxScore = ul.clamp(mgrInteraction.playBallMaxScore * 1.35, 50, 1000000);
                selfScore = mgrInteraction.playBallMaxScore;
            }
            else if (rankId == eNearbyRankId.learn) {
                maxScore = ul.clamp(mgrInteraction.historyLearnRightQuestionCount * 1.35, 50, 1000000);
                selfScore = mgrInteraction.historyLearnRightQuestionCount;
            }
            let players = [];
            for (let i = 1; i <= 49; i++) {
                players.push(this.randomOnePlayer(maxScore));
            }
            players = Tools.sortArrayByField(players, "-score");
            for (let i = 0; i < players.length; i++) {
                const element = players[i];
                element.rank = i + 1;
            }
            return players;
        }
        static randomOnePlayer(maxScore) {
            let player = {
                name: mgrPlayer.calcRandomName(),
                uid: Tools.generateUUID(),
                distance: Tools.random(DISTANCE_RANGE[0], DISTANCE_RANGE[1]),
                score: Tools.random(maxScore),
                rank: 0,
            };
            return player;
        }
        static randomChangePlayerForRank(rankId, players) {
            let maxScore = 0;
            let selfScore = 0;
            if (rankId == eNearbyRankId.garden) {
                maxScore = mgrGarden.getMaxCollectAmount();
                selfScore = mgrGarden.getMyCollectAmount();
            }
            else if (rankId == eNearbyRankId.stage) {
                maxScore = mgrStage.getTotalStageCount();
                selfScore = mgrStage.getStageProgress();
            }
            else if (rankId == eNearbyRankId.ropeSkiping) {
                maxScore = ul.clamp(mgrInteraction.ropeSkippingMaxScore * 1.35, 50, 1000000);
                selfScore = mgrInteraction.ropeSkippingMaxScore;
            }
            else if (rankId == eNearbyRankId.playBall) {
                maxScore = ul.clamp(mgrInteraction.playBallMaxScore * 1.35, 50, 1000000);
                selfScore = mgrInteraction.playBallMaxScore;
            }
            else if (rankId == eNearbyRankId.learn) {
                maxScore = ul.clamp(mgrInteraction.historyLearnRightQuestionCount * 1.35, 50, 1000000);
                selfScore = mgrInteraction.historyLearnRightQuestionCount;
            }
            for (let i = 0; i < players.length; i++) {
                const player = players[i];
                if (player.uid == mgrPlayer.getUid()) {
                    player.name = mgrPlayer.getName();
                    player.score = selfScore;
                }
                else {
                    player.distance += Tools.random(DISTANCE_DELTA_RANGE[0], DISTANCE_DELTA_RANGE[1]);
                    player.distance = ul.clamp(player.distance, DISTANCE_RANGE[0], DISTANCE_RANGE[1]);
                    player.score = Math.floor(ul.clamp(Tools.random(maxScore), player.score, maxScore));
                }
            }
            players = Tools.sortArrayByField(players, "-score");
            for (let i = 0; i < players.length; i++) {
                const element = players[i];
                element.rank = i + 1;
            }
            return players;
        }
        static updateSelfInfo() {
            let needShowRankIds = [eNearbyRankId.learn, eNearbyRankId.garden, eNearbyRankId.playBall, eNearbyRankId.ropeSkiping, eNearbyRankId.stage];
            for (let i = 0; i < needShowRankIds.length; i++) {
                const rankId = needShowRankIds[i];
                let selfScore = 0;
                if (rankId == eNearbyRankId.garden) {
                    selfScore = mgrGarden.getMyCollectAmount();
                }
                else if (rankId == eNearbyRankId.stage) {
                    selfScore = mgrStage.getStageProgress();
                }
                else if (rankId == eNearbyRankId.ropeSkiping) {
                    selfScore = mgrInteraction.ropeSkippingMaxScore;
                }
                else if (rankId == eNearbyRankId.playBall) {
                    selfScore = mgrInteraction.playBallMaxScore;
                }
                else if (rankId == eNearbyRankId.learn) {
                    selfScore = mgrInteraction.historyLearnRightQuestionCount;
                }
                let bUpadatedSelf = false;
                let players = this.players[rankId];
                for (let i = 0; i < players.length; i++) {
                    const player = players[i];
                    if (player.uid == mgrPlayer.getUid()) {
                        player.name = mgrPlayer.getName();
                        player.score = selfScore;
                        bUpadatedSelf = true;
                        break;
                    }
                }
                if (!bUpadatedSelf) {
                    let selfPlayer = {
                        uid: mgrPlayer.getUid(),
                        name: mgrPlayer.getName(),
                        distance: 0,
                        score: selfScore,
                        rank: 0,
                    };
                    players.push(selfPlayer);
                }
                players = Tools.sortArrayByField(players, "-score");
                for (let i = 0; i < players.length; i++) {
                    const element = players[i];
                    element.rank = i + 1;
                }
                this.players[rankId] = players;
                this.saveRecord();
            }
        }
        static getPlayersByRankId(rankId) {
            return this.players[rankId];
        }
        static getOwnInfoByRankId(rankId) {
            for (let index = 0; index < this.players[rankId].length; index++) {
                const element = this.players[rankId][index];
                if (element.uid == mgrPlayer.getUid())
                    return element;
            }
        }
        static onMsgPlayerNameChanged() {
            this.updateSelfInfo();
            this.sendMsg("MSG_NEARBY_RANK_REFRESH");
        }
    }

