        static randomSeriesQuestion(id) {
            let question = {
                questionId: id,
                param1: "",
                param2: 0,
                sign: "ADD",
                answer1: 0,
                answer2: 0,
                realAnswer: 0,
            };
            let type = Tools.random(1, 3);
            if (type == 1) {
                let start = Tools.random(0, 5);
                let factor = Tools.random(1, 5);
                question.param1 += `${start},`;
                question.param1 += `${start + factor},`;
                question.param1 += `${start + 2 * factor},`;
                question.param1 += `?`;
                question.realAnswer = start + 3 * factor;
                if (Math.random() > 0.5) {
                    question.answer1 = question.realAnswer;
                    question.answer2 = question.realAnswer + Tools.random(10);
                }
                else {
                    question.answer1 = question.realAnswer + Tools.random(10);
                    question.answer2 = question.realAnswer;
                }
            }
            else if (type == 2) {
                let start = Tools.random(1, 4);
                let factor = Tools.random(2, 4);
                question.param1 += `${start},`;
                question.param1 += `${start * factor},`;
                question.param1 += `${start * factor * factor},`;
                question.param1 += `?`;
                question.realAnswer = start * factor * factor * factor;
                if (Math.random() > 0.5) {
                    question.answer1 = question.realAnswer;
                    question.answer2 = question.realAnswer + Tools.random(10);
                }
                else {
                    question.answer1 = question.realAnswer + Tools.random(10);
                    question.answer2 = question.realAnswer;
                }
            }
            else if (type == 3) {
                let start = Tools.random(0, 1);
                let start2 = 1;
                question.param1 += `${start},`;
                question.param1 += `${start2},`;
                question.param1 += `${start + start2},`;
                question.param1 += `${start + start2 + start2},`;
                question.param1 += `?`;
                question.realAnswer = start + start2 + start2 + start + start2;
                if (Math.random() > 0.5) {
                    question.answer1 = question.realAnswer;
                    question.answer2 = question.realAnswer + Tools.random(10);
                }
                else {
                    question.answer1 = question.realAnswer + Tools.random(10);
                    question.answer2 = question.realAnswer;
                }
            }
            return question;
        }
