    class Queue {
        constructor() {
            this._queue = [];
            this.id = Tools.time() * 10000;
        }
        push(element) {
            if (!element)
                return;
            this._queue.push(element);
        }
        pop() {
            return this._queue.shift();
        }
        clear() {
            this._queue = [];
        }
        length() {
            return this._queue.length;
        }
        getElement(index) {
            return this._queue[index];
        }
    }

    let wx = window[`wx`];
    let tt = window[`tt`];
    const DEFAULT_SAMPLE_RATE = 8000;
    class SoundLibary {
        static get bCanRecord() {
            return !!wx && !tt;
        }
        static get fileManager() {
            if (!this.__fileManager)
                this.__fileManager = wx.getFileSystemManager();
            return this.__fileManager;
        }
        static get audioRecoder() {
            if (!this.__audioRecoder)
                this.__audioRecoder = wx.getRecorderManager();
            return this.__audioRecoder;
        }
        static playSound(url, callback) {
            let audioContext = wx.createInnerAudioContext();
            audioContext.src = url;
            audioContext.play();
            audioContext.onEnded(() => {
                audioContext.destroy();
                callback();
            });
        }
        static writeString(data, offset, str, littleEndia = false) {
            for (let i = 0; i < str.length; i++) {
                let code = str.charCodeAt(i);
                data.setUint8(offset, code);
                offset += 1;
            }
        }
        static getString(data, offset, count) {
            let str = "";
            for (let i = 0; i < count; i++) {
                let charCode = data.getUint8(offset);
                offset += 1;
                str += String.fromCharCode(charCode);
            }
            return str;
        }
        static pcm2wav(pcmBuffer, wavPath, channelCount = 1, sampleRate = DEFAULT_SAMPLE_RATE, sampleBits = 16) {
            console.log("pcm2wav Parms:", pcmBuffer, wavPath, channelCount, sampleRate, sampleBits);
            let wavBuffer = new ArrayBuffer(pcmBuffer.byteLength + 44);
            let dataPcm = new DataView(pcmBuffer);
            let dataWav = new DataView(wavBuffer);
            let offset = 0;
            this.writeString(dataWav, offset, 'RIFF');
            offset += 4;
            dataWav.setUint32(offset, 36 + dataPcm.byteLength, true);
            offset += 4;
            this.writeString(dataWav, offset, 'WAVE');
            offset += 4;
            this.writeString(dataWav, offset, 'fmt ');
            offset += 4;
            dataWav.setUint32(offset, 16, true);
            offset += 4;
            dataWav.setUint16(offset, 1, true);
            offset += 2;
            dataWav.setUint16(offset, channelCount, true);
            offset += 2;
            dataWav.setUint32(offset, sampleRate, true);
            offset += 4;
            dataWav.setUint32(offset, channelCount * sampleRate * (sampleBits / 8), true);
            offset += 4;
            dataWav.setUint16(offset, channelCount * (sampleBits / 8), true);
            offset += 2;
            dataWav.setUint16(offset, sampleBits, true);
            offset += 2;
            this.writeString(dataWav, offset, 'data');
            offset += 4;
            dataWav.setUint32(offset, dataPcm.byteLength, true);
            offset += 4;
            for (let i = 0; i < dataPcm.byteLength; ++i) {
                dataWav.setUint8(offset, dataPcm.getUint8(i));
                offset++;
            }
            this.fileManager.writeFileSync(wavPath, wavBuffer, "binary");
        }
        static parseWavHead(path) {
            let buffer = this.fileManager.readFileSync(path);
            let dataWav = new DataView(buffer);
            let head = {};
            let offset = 0;
            head.ChunkID = this.getString(dataWav, offset, 4);
            offset += 4;
            head.ChunkSize = dataWav.getUint32(offset, true);
            offset += 4;
            head.Format = this.getString(dataWav, offset, 4);
            offset += 4;
            head.Subchunk1ID = this.getString(dataWav, offset, 4);
            offset += 4;
            head.Subchunk1Size = dataWav.getUint32(offset, true);
            offset += 4;
            head.AudioFormat = dataWav.getUint16(offset, true);
            offset += 2;
            head.NumChannels = dataWav.getUint16(offset, true);
            offset += 2;
            head.SampleRate = dataWav.getUint32(offset, true);
            offset += 4;
            head.ByteRate = dataWav.getUint32(offset, true);
            offset += 4;
            head.BlockAlign = dataWav.getUint16(offset, true);
            offset += 2;
            head.BitsPerSample = dataWav.getUint16(offset, true);
            offset += 2;
            head.Subchunk2Id = this.getString(dataWav, offset, 4);
            offset += 4;
            head.Subchunk2Size = dataWav.getUint32(offset, true);
            return head;
        }
        static startRecord(sampleRate = DEFAULT_SAMPLE_RATE, channelCount = 1, sampleBits = 16, format = 'pcm', duration = 10 * 1000, frameSize = DEFAULT_SAMPLE_RATE * 2 / 1024) {
            let options = {
                duration: duration,
                sampleRate: sampleRate,
                numberOfChannels: channelCount,
                encodeBitRate: sampleRate * channelCount * sampleBits / 8,
                format: format,
                frameSize: frameSize,
            };
            this.audioRecoder.start(options);
            this.audioRecoder.onStart(() => {
                console.log('recorder start');
                console.log(options);
            });
        }
        static stopRecord() {
            this.audioRecoder.stop();
        }
        static setStopCallback(callback) {
            this.audioRecoder.onStop((res) => {
                callback(res);
            });
        }
        static setFrameSizeCallback(callback) {
            let count = 0;
            this.audioRecoder.onFrameRecorded((res) => {
                count++;
                res.count = count;
                callback(res);
            });
        }
        static resampleData(sourceBuffer, sampleRate, newSampleRate) {
            let sourceData = new Int16Array(sourceBuffer);
            let srcSize = sourceData.length;
            if (sampleRate == newSampleRate) {
                return sourceBuffer;
            }
            let last_pos = srcSize - 1;
            let dstSize = Math.floor(srcSize * (newSampleRate / sampleRate));
            let newArrayBuffer = new ArrayBuffer(dstSize * 2);
            let destinationData = new Int16Array(newArrayBuffer);
            for (let idx = 0; idx < dstSize; idx++) {
                let index = idx * sampleRate / newSampleRate;
                let p1 = Math.floor(index);
                let coef = index - p1;
                let p2 = (p1 == last_pos) ? last_pos : p1 + 1;
                destinationData[idx] = Math.floor((1 - coef) * sourceData[p1] + coef * sourceData[p2]);
            }
            return newArrayBuffer;
        }
        static isSampleDataUserful(arrayBuffer) {
            return true;
        }
        static createPcmQueue() {
            let queue = new Queue();
            this.validPcmQueues[queue.id] = queue;
            return queue.id;
        }
        static destroyAllPcmQueue() {
            console.log(`destroyAllPcmQueue`);
            for (const k in this.validPcmQueues) {
                let queue = this.validPcmQueues[k];
                if (!queue)
                    continue;
                queue.clear();
            }
            this.validPcmQueues = {};
        }
        static destroyPcmQueue(id) {
            console.log(`destroyPcmQueue: ${id}`);
            let queue = this.validPcmQueues[id];
            if (!queue)
                return;
            queue.clear();
            this.validPcmQueues[id] = null;
        }
        static addPcm2Queue(pcmBuffer, id) {
            if (!this.validPcmQueues || !this.validPcmQueues[id])
                return;
            this.validPcmQueues[id].push(pcmBuffer);
        }
        static playValidQueue(id, newSampleRate = DEFAULT_SAMPLE_RATE, callback) {
            let queue = this.validPcmQueues[id];
            if (!queue || queue.length() <= 0) {
                callback && callback();
            }
            let totalByteLength = 0;
            for (let index = 0; index < queue.length(); index++) {
                const element = queue.getElement(index);
                totalByteLength += element.byteLength;
                console.log(`element.byteLength:${element.byteLength}`);
            }
            console.log(`totalByteLength:${totalByteLength}`);
            let array2 = [];
            let newArrayBuffer = new ArrayBuffer(totalByteLength);
            let newData = new Int16Array(newArrayBuffer);
            let __newDataindex = 0;
            for (let index = 0; index < queue.length(); index++) {
                const element = queue.getElement(index);
                let oldData = new Int16Array(element);
                for (let __oldDataIndex = 0; __oldDataIndex < oldData.length; __oldDataIndex++) {
                    const num = oldData[__oldDataIndex];
                    newData[__newDataindex] = num;
                    __newDataindex++;
                    if (!array2[num])
                        array2[num] = 0;
                    array2[num]++;
                }
            }
            console.log(`oldPcmBuffer`);
            let array = [];
            for (let index = 0; index < newData.length; index++) {
                const element = newData[index];
                if (!array[element])
                    array[element] = 0;
                array[element]++;
            }
            console.log(`newPcmBuffer`);
            let pcmBuffer = SoundLibary.resampleData(newArrayBuffer, DEFAULT_SAMPLE_RATE, newSampleRate);
            let wavPath = `${wx.env.USER_DATA_PATH}/temp_${Tools.time() * 1000}.wav`;
            console.log(`wav path: ${wavPath}`);
            SoundLibary.pcm2wav(pcmBuffer, wavPath);
            SoundLibary.playSound(wavPath, () => {
                SoundLibary.fileManager.unlinkSync(wavPath);
                callback && callback();
            });
        }
        static recoderVaildVoice(frequencyFactor, vaildCallback, playCallback, finishCallback) {
            try {
                let queueId = this.createPcmQueue();
                console.log(`queueId: ${queueId}`);
                let bHaveVoice = false;
                let bStop = false;
                SoundLibary.startRecord();
                SoundLibary.setFrameSizeCallback((res) => {
                    console.log("=== 每帧回调 ====");
                    console.log(res);
                    if (SoundLibary.isSampleDataUserful(res.frameBuffer)) {
                        vaildCallback && vaildCallback();
                        bHaveVoice = true;
                    }
                    else {
                        if (bHaveVoice) {
                            if (!bStop) {
                                SoundLibary.stopRecord();
                                bStop = true;
                            }
                        }
                    }
                    if (bHaveVoice) {
                        this.addPcm2Queue(res.frameBuffer, queueId);
                    }
                    if (res.isLastFrame) {
                        playCallback && playCallback();
                        this.playValidQueue(queueId, DEFAULT_SAMPLE_RATE / frequencyFactor, () => {
                            this.destroyPcmQueue(queueId);
                            finishCallback && finishCallback();
                        });
                    }
                });
                SoundLibary.setStopCallback((res) => {
                    console.log("结束回调");
                    SoundLibary.fileManager.unlinkSync(res.tempFilePath);
                });
            }
            catch (error) {
                console.log(error);
            }
        }
    }
    SoundLibary.validPcmQueues = {};

