    class mgrDailyTask extends Manager {
        static onLoad() {
            super.onLoad();
            mgrCfg.forDb_from_daily_task_config_db((key, value) => {
                this._rewardDatas[value.id] = value;
            });
            this.loadRecord();
            if (!Tools.isOneDay(this.lastRefreshTime, Tools.time())) {
                this._rewardsTaked = [];
                this.lastRefreshTime = Tools.time();
            }
        }
        static loadRecord() {
            super.loadRecord();
            let record = mgrRecord.getData("dailyTask") || {};
            this._rewardsTaked = record._rewardsTaked || [];
            this.lastRefreshTime = record.lastRefreshTime || 0;
        }
        static saveRecord() {
            super.saveRecord();
            let record = {
                _rewardsTaked: this._rewardsTaked,
                lastRefreshTime: this.lastRefreshTime,
            };
            mgrRecord.setData("dailyTask", record);
        }
        static getActiveCount() {
            let activeCount = 0;
            mgrCfg.forDb_from_achievement_db((k, v) => {
                if (v.category == 1) {
                    let achievement = mgrAchievement.getAchievement(v.id);
                    if (achievement.state == AchievementState.received) {
                        activeCount++;
                    }
                }
            });
            return activeCount;
        }
        static getRewardIndex() {
            let index = 1;
            while (true) {
                if (!mgrDailyTask.isGetedRewards(index))
                    break;
                index++;
            }
            index = ul.clamp(index, 1, ul.length(mgrCfg.getDb(`daily_task_config_db`)));
            return index;
        }
        static getRewardDatas() {
            return this._rewardDatas;
        }
        static getTaskIds() {
            let index = this.getRewardIndex();
            let datas = this.getRewardDatas();
            let data = datas[index];
            return data.aids;
        }
        static getCanFinishTaskIds() {
            let canFinishIds = [];
            let ids = this.getTaskIds();
            for (let index = 0; index < ids.length; index++) {
                const id = ids[index];
                if (this.__canFinish(id)) {
                    canFinishIds.push(id);
                }
            }
            return canFinishIds;
        }
        static isGetedRewards(idx) {
            if (this._rewardsTaked.indexOf(idx) >= 0) {
                return true;
            }
            return false;
        }
        static canObtainReward(idx, bshowTip = true) {
            if (this.isGetedRewards(idx)) {
                bshowTip && mgrTip.showMsgTip("已领取");
                return false;
            }
            let data = this._rewardDatas[idx];
            let starCount = this.getActiveCount();
            if (starCount < data.targetActiveCount) {
                bshowTip && mgrTip.showMsgTip("活跃度不足，请完成更多任务");
                return false;
            }
            return true;
        }
        static obtainReward(idx, ratio = 1) {
            if (this.isGetedRewards(idx)) {
                mgrTip.showMsgTip("已领取");
                return false;
            }
            let data = this._rewardDatas[idx];
            let starCount = this.getActiveCount();
            this._rewardsTaked.push(idx);
            this.saveRecord();
            let itemId = data.rewardItemId;
            let amount = data.rewardAmount;
            mgrPlayer.addItemAmount(itemId, amount * ratio, "日常任务发奖");
            mgrTip.addGotItemTip(itemId, amount * ratio, null, {
                fOnClose: () => {
                }
            });
            mgrSdk.staticPointEvent(8000);
            return true;
        }
        static getBadageCount() {
            let taskIds = this.getCanFinishTaskIds();
            for (const k in taskIds) {
                let taskId = taskIds[k];
                let task = mgrAchievement.getAchievement(taskId);
                if (task && task.state == AchievementState.finished)
                    return 1;
            }
            for (const k in this._rewardDatas) {
                if (this.canObtainReward(parseInt(k), false)) {
                    return 1;
                }
            }
            return 0;
        }
        static __canFinish(taskId) {
            let achievementData = mgrCfg.get_from_achievement_db(taskId);
            if (achievementData.targetType == 14 && !mgrChannel.canShare()) {
                return false;
            }
            if (achievementData.targetType == 13) {
                return false;
            }
            return true;
        }
    }
    mgrDailyTask._rewardsTaked = [];
    mgrDailyTask._rewardDatas = [];

    const MINUTE_INCOME = Math.floor(750 / 60);
    const OFFLINE_MAX_TIME = 60 * 60 * 8;
    const OFFLINE_SETTLE_MIN_TIME = 60 * 60;
    class mgrOfflineReward extends Manager {
        static onLoad() {
            super.onLoad();
            this.loadRecord();
            this.trySettlementLastOfflineTime();
            this.goOfflineTime = Tools.time();
            Timer.callLoop(60, () => {
                this.goOfflineTime = Tools.time();
                this.saveRecord();
            }, true);
        }
        static loadRecord() {
            super.loadRecord();
            let record = mgrRecord.getData("offline_reward") || {};
            this.goOfflineTime = record.goOfflineTime || Tools.time();
            this.willSettlementOfflineTimeQueue = record.willSettlementOfflineTimeQueue || [];
            this.saveRecord();
        }
        static saveRecord() {
            super.saveRecord();
            let record = {
                goOfflineTime: this.goOfflineTime,
                willSettlementOfflineTimeQueue: this.willSettlementOfflineTimeQueue,
            };
            mgrRecord.setData("offline_reward", record);
        }
        static trySettlementLastOfflineTime() {
            let goOnlineTime = Tools.time();
            let deltaTime = Math.floor(goOnlineTime - this.goOfflineTime);
            if (deltaTime >= OFFLINE_SETTLE_MIN_TIME) {
                this.willSettlementOfflineTimeQueue.push(deltaTime);
                let time = this.goOfflineTime;
                mgrGuide.isAllGuideFinished() && Timer.callLater(0.016, () => {
                    mgrInteraction.restState = E_REST_STATE.rest;
                    mgrInteraction.lastRefreshTime = time;
                }, this);
                return true;
            }
            else {
                return false;
            }
        }
        static getOfflineReward() {
            let pastTime = 0;
            let income = 0;
            for (let index = 0; index < this.willSettlementOfflineTimeQueue.length; index++) {
                const time = this.willSettlementOfflineTimeQueue[index];
                pastTime += time;
            }
            pastTime = pastTime > OFFLINE_MAX_TIME ? OFFLINE_MAX_TIME : pastTime;
            income = Math.ceil(pastTime / 60 * MINUTE_INCOME);
            return [pastTime, income];
        }
        static markOfflineRewardGeted() {
            this.willSettlementOfflineTimeQueue = [];
            this.goOfflineTime = Tools.time();
            this.saveRecord();
        }
    }
    mgrOfflineReward.goOfflineTime = 0;
    mgrOfflineReward.willSettlementOfflineTimeQueue = [];

