    class vWarpSceneNode extends ViewBase {
        constructor(context) {
            super(context);
            this.sourceName = "node/vWarpSceneNode";
            this.exportNodeNames = [
                "CC_spriteBg",
                "CC_imageMask",
                "CC_imageFlower",
            ];
        }
        onOpened() {
            this.spriteBg.cacheAs = "bitmap";
            this.imageMask.blendMode = "destination-out";
            this.imageMask.graphics.clear();
            this.imageMask.graphics.drawCircle(this.imageMask.width / 2, this.imageMask.height / 2, this.imageMask.width / 2, `#ff0000`);
            if (this.bPlayingClose) {
                this.playCloseAnimation(this.closeCallback.bind(this), true);
            }
        }
        onClosed() {
        }
        playCloseAnimation(callback, force = false) {
            if (this.bPlayingClose && !force)
                return;
            this.bPlayingClose = true;
            this.closeCallback = callback;
            if (!this.bResLoaded)
                return;
            this.spriteBg.alpha = 0;
            this.spriteBg.scale(8, 8);
            this.imageFlower.alpha = 0;
            this.imageFlower.rotation = 90;
            CustomTween.to(this.spriteBg, { alpha: 1 }, 200).to({ scaleX: 1, scaleY: 1 }, 500)
                .delayTime(300)
                .callback(() => {
                this.bPlayingClose = false;
                this.closeCallback && this.closeCallback();
            })
                .start(1);
            CustomTween.delayTime(this.imageFlower, 500).to({ alpha: 1, rotation: 0 }, 500)
                .callback(() => {
                CustomTween.rotateForever(this.imageFlower, 6000, false);
            })
                .start(1);
        }
        playOpenAnimation() {
            this.spriteBg.alpha = 1;
            this.spriteBg.scale(1, 1);
            this.imageFlower.alpha = 1;
            this.imageFlower.rotation = 90;
            CustomTween.to(this.spriteBg, { scaleX: 8, scaleY: 8 }, 500).to({ alpha: 0 }, 200)
                .callback(() => {
                this.spriteBg.alpha = 0;
            })
                .start(1);
            CustomTween.to(this.imageFlower, { alpha: 0 }, 500).start(1);
        }
    }

    const ST_READ_HEAD = 1;
    const ST_READ_DATA = 2;
    class SeasionWS extends Laya.EventDispatcher {
        constructor() {
            super();
            this.instanceId = 0;
            this.uuid = null;
            this.revDataBuffer = "";
            this.socket = null;
            this.readState = ST_READ_HEAD;
            this.head = {};
            this.instanceId = 0;
            this.uuid = null;
            this.revDataBuffer = "";
            this.socket = null;
            this.readState = ST_READ_HEAD;
            this.head = {};
        }
        setUuid(uuid) {
            this.uuid = uuid;
        }
        setSocket(socket) {
            this.socket = socket;
            this.socket.onopen = () => {
                this.event('open');
            };
            this.socket.onclose = () => {
                this.event("close");
            };
            this.socket.onerror = (errEvent) => {
                this.event("error");
            };
            this.socket.onmessage = (msgEvent) => {
                this.revDataBuffer += msgEvent.data;
                if (this.readState == ST_READ_HEAD) {
                    let rep = /({.+?})/;
                    let result = rep.exec(this.revDataBuffer);
                    if (!!result) {
                        let headStr = result.shift();
                        this.revDataBuffer = this.revDataBuffer.replace(headStr, "");
                        this.head = JSON.parse(headStr);
                        this.readState = ST_READ_DATA;
                    }
                }
                if (this.readState == ST_READ_DATA) {
                    if (this.revDataBuffer.length >= this.head.dataLength) {
                        let dataStr = this.revDataBuffer.slice(0, this.revDataBuffer.length);
                        try {
                            let data = JSON.parse(dataStr);
                            this.event("data", data);
                        }
                        catch (error) {
                            console.error("ST_READ_DATA error:", error);
                        }
                        this.revDataBuffer = this.revDataBuffer.replace(dataStr, "");
                        this.readState = ST_READ_HEAD;
                    }
                }
            };
        }
        write(data) {
            let content = JSON.stringify(data);
            let head = {
                dataLength: content.length,
            };
            this.socket.send(JSON.stringify(head) + content);
        }
        close() {
            this.socket.close();
        }
    }

    class NetworkWS {
        static newSeasion(ip, port) {
            let address = 'ws://' + ip + ':' + port.toString();
            console.log("Địa chỉ kết nối:", address);
            let client = new WebSocket(address);
            let seasionWs = new SeasionWS();
            seasionWs.setSocket(client);
            return seasionWs;
        }
    }

    class GameRemoteRouter {
        constructor(seasion) {
            this.__seasion = null;
            this.__registedRouter = null;
            this.seasion = seasion;
            if (!this.seasion) {
                console.error("没有设置seasion");
                return;
            }
            this.seasion.on('data', this, (data) => {
                this.__router(data);
            });
        }
        get seasion() {
            return this.__seasion;
        }
        set seasion(value) {
            this.__seasion = value;
        }
        sendMsgToServer(reqData) {
            this.seasion.write(reqData);
        }
        registerRouter(route, callback) {
            if (!!route && !!callback) {
                this.__registedRouter[route] = callback;
            }
        }
        __router(data) {
            if (!data)
                return;
            if (!data.route)
                return;
            if (!this.__registedRouter[data.route])
                return;
            let router = this.__registedRouter[data.route];
            router(data.data);
        }
    }

    class vLoadingScene extends SceneBase {
        constructor(context) {
            super(context);
            this.sourceName = "scene/vLoadingScene";
            this.exportNodeNames = [
                "CC_progressBarProgress",
                "CC_spriteBar",
                "CC_spriteXingxing",
                "CC_labelTipAuthor",
                "CC_spriteLogo",
                "CC_spriteLogoNative",
                "CC_boxProgress",
            ];
            this.curProgress = 0;
            this.fakeProgress = 0;
        }
        onOpened() {
            super.onOpened();
            if (window[`conch`]) {
                this.labelTipAuthor.visible = true;
                this.spriteLogo.visible = false;
                this.spriteLogoNative.visible = true;
            }
            else {
                this.labelTipAuthor.visible = false;
                this.spriteLogo.visible = true;
                this.spriteLogoNative.visible = false;
            }
            for (let i = 1; i <= 7; i++) {
                this[`star${i}`] = new ULSkeleton("res/spine/ui_loading.sk");
                this[`star${i}`].playAnimation("idle1");
                this.boxProgress.addChild(this[`star${i}`]);
                Tools.layoutH(this.boxProgress, 476 / 6);
            }
            CustomTween.to(this.spriteXingxing, { rotation: 360 }, 2000).callback(() => { this.spriteXingxing.rotation = 0; }).start(0);
            CustomTween.from(this.spriteLogo, { x: this.spriteLogo.x - 576 }, 500, Laya.Ease.backOut).start(1);
            CustomTween.from(this.spriteLogoNative, { x: this.spriteLogo.x - 576 }, 500, Laya.Ease.backOut).start(1);
            this.beginLoading();
            this.registerListeners({
                MSG_SDK_CHANNEL_INFO_RESULT: this.onMsgChannelInfoResult.bind(this),
            });
            this.updateProgress();
            this.updateTimer = Timer.callLoop(0.016, () => { this.updateProgress(); }, this);
        }
        onClosed() {
            super.onClosed();
        }
        beginLoading() {
            this.context.beginTime = Tools.time();
            let taskManager = new TaskManager((progress, total) => {
                this.curProgress = progress / total;
            });
            let taskSamples = [];
            taskSamples.push((finishCallback) => {
                console.log("==>初始化自定义shader");
                CartoonMaterial.initShader();
                finishCallback();
            });
            let cfgUrls = mgrCfg.getLoadUrls();
            for (const k in cfgUrls) {
                let url = cfgUrls[k];
                taskSamples.push((finishcallback) => {
                    console.log(`加载配置表: ${url}`);
                    Laya.loader.load(url, new Laya.Handler(this, (obj) => {
                        if (obj) {
                            finishcallback();
                        }
                    }));
                });
            }
            taskManager.push(taskSamples);
            taskManager.push([(finishCallback) => {
                    console.log("处理加载完毕事宜!!");
                    this.initGameData(finishCallback);
                }]);
            taskSamples = [];
            let defaultPartModelIds = [
                `item_huabao`,
                `map_hudong`,
            ];
            if (window[`conch`]) {
                defaultPartModelIds.push(`fairy_001_toufa`);
                defaultPartModelIds.push(`fairy_001_yifu`);
            }
            for (let index = 0; index < defaultPartModelIds.length; index++) {
                const modelId = defaultPartModelIds[index];
                taskSamples.push((finishCallback) => {
                    mgrLoader.loadModeWithModeId(modelId, () => {
                        this.add3DEffectAtFront(modelId, { x: 10000, y: 10000 }, 1);
                        Timer.callLater(1, () => {
                            finishCallback();
                        }, this);
                    }, this, 0);
                });
            }
            taskManager.push(taskSamples);
            taskManager.start(() => {
                let usedTime = Tools.time() - this.context.beginTime;
                console.log(`加载完毕, 总共用时: ${usedTime * 1000}毫秒`);
                mgrSdk.onLoadingComplete();
                vLoadingScene.bInit = true;
            });
        }
        initGameData(finishCallback) {
            mgrCfg.processDb();
            this.__importAllManager();
            Manager.loadAllManagers(finishCallback);
            ScaleButton.setSoundPlayId(101);
        }
        __importAllManager() {
            let allNeedImportManager = [
                mgrNative,
                mgrRecord,
                mgrSound,
                mgrCfg,
                mgrPlayer,
                mgrInteraction,
                mgrDirector,
                mgrSdk,
                mgrTip,
                mgrDebug,
                mgrAd,
                mgrCop,
                mgrStage,
                mgrOfflineArena,
                mgrOfflinePartRank,
                mgrOfflinePvp,
                mgrOfflineLevelRank,
                mgrGarden,
                mgrPart,
                mgrWishPool,
                mgrSign,
                mgrAchievement,
                mgrDailyTask,
                mgrGuide,
                mgrShop,
                mgrLoader,
                mgrChannel,
                mgrReview,
                mgrAdNative,
                mgrNativeAdSdk,
                mgrOfflineNearbyRank,
                mgrOfflineReward,
            ];
            for (let index = 0; index < allNeedImportManager.length; index++) {
                const element = allNeedImportManager[index];
                element.__init();
            }
        }
        updateProgress() {
            let factor = 0.05;
            this.fakeProgress = this.fakeProgress * (1 - factor) + this.curProgress * factor;
            this.progressBarProgress.progress = this.fakeProgress;
            this.spriteXingxing.x = this.spriteBar.width * this.fakeProgress;
            for (let i = 0; i <= 6; i++) {
                let skeleton = this[`star${i + 1}`];
                if (this.fakeProgress >= (i / 6 - 0.1) && skeleton.playingAnimationName == "idle1") {
                    skeleton.playAnimation("idle2", false, () => {
                        skeleton.playAnimation("idle3", true);
                    });
                }
            }
            if (this.fakeProgress >= 0.99) {
                this.updateTimer.stop();
                this.startGame();
            }
        }
        startGame() {
            if (!window[`swan`]) {
                let seasion = NetworkWS.newSeasion(`127.0.0.1`, 8081);
                seasion.on("open", this, () => {
                    Timer.callLater(1, () => {
                        mgrTip.showMsgTip("Đã kết nối thành công với máy chủ lưu dữ liệu! Giờ đây bạn có thể lưu dữ liệu!");
                    });
                    Const.GlobalRouter = new GameRemoteRouter(seasion);
                });
                seasion.on("error", this, () => {
                    console.log("Không thể kết nối với máy chủ lưu trữ!");
                });
            }
            if (!mgrInteraction.bBorn) {
                mgrDirector.open2DScene(`vBornScene`);
            }
            else {
                mgrDirector.warpSceneWidthEffect("vHubScene", {
                    bFromLoading: true,
                });
            }
        }
        onMsgChannelInfoResult() {
            console.log("收到初始化回调!!!");
            mgrOfflineNearbyRank.updateSelfInfo();
        }
    }

