        static _origin_sortTiles(arr) {
            let isCover = (a, b) => {
                return b.right > a.x && b.top > a.y;
            };
            let sortedArr = [];
            let len = arr.length;
            for (let i = 0; i < len; i++) {
                let a = arr[i];
                let indexA = sortedArr.indexOf(a);
                for (let j = 0, len = arr.length; j < len; j++) {
                    if (i == j)
                        continue;
                    let b = arr[j];
                    if (isCover(a, b)) {
                        let indexB = sortedArr.indexOf(b);
                        if (indexA < 0) {
                            sortedArr.push(a);
                            indexA = sortedArr.length - 1;
                        }
                        if (indexB < 0) {
                            sortedArr.push(b);
                            indexB = sortedArr.length - 1;
                        }
                        if (indexB < indexA) {
                            sortedArr.splice(indexA, 1);
                            sortedArr.splice(indexB, 0, a);
                            indexA = indexB;
                        }
                    }
                }
            }
            for (let i = 0; i < arr.length; i++) {
                let a = arr[i];
                if (sortedArr.indexOf(a) < 0) {
                    sortedArr.push(a);
                }
            }
            return sortedArr;
        }
        static sortTiles(arr) {
            let isCover = (a, b) => {
                return b.right > a.x && b.top > a.y;
            };
            for (let i = 0; i < arr.length; i++) {
                const v = arr[i];
                v._id = i;
            }
            let sortedArr = [];
            let indexCache = {};
            let len = arr.length;
            for (let i = 0; i < len; i++) {
                let a = arr[i];
                let indexA = indexCache[a._id];
                for (let j = 0; j < len; j++) {
                    if (i == j)
                        continue;
                    let b = arr[j];
                    if (isCover(a, b)) {
                        let indexB = indexCache[b._id];
                        if (indexA == null) {
                            sortedArr.push(a);
                            indexA = sortedArr.length - 1;
                            indexCache[a._id] = indexA;
                        }
                        if (indexB == null) {
                            sortedArr.push(b);
                            indexB = sortedArr.length - 1;
                            indexCache[b._id] = indexB;
                        }
                        if (indexB < indexA) {
                            for (let k = indexB; k < indexA; k++) {
                                let temp = sortedArr[k];
                                indexCache[temp._id]++;
                            }
                            sortedArr.splice(indexA, 1);
                            sortedArr.splice(indexB, 0, a);
                            indexA = indexB;
                            indexCache[a._id] = indexA;
                        }
                    }
                }
            }
            for (let i = 0; i < arr.length; i++) {
                let a = arr[i];
                if (indexCache[a._id] == null) {
                    sortedArr.push(a);
                }
            }
            return sortedArr;
        }
