    class vFoodShopDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vFoodShopDialog";
            this.exportNodeNames = [
                "CC_boxList",
                "CC_spriteBasket",
                "CC_boxBasket",
                "CC_buttonClose",
                "CC_labelRightFreeWish",
                "CC_spriteNativeEmbed",
                "CC_spriteNativeIcon",
                "CC_labelNativeTitle",
                "CC_labelNativeDesc",
                "CC_buttonNativeGo",
                "CC_labelNativeGo",
                "CC_spriteNativeAdTag",
            ];
            this.yDistance = 20;
            this.xDistance = 40;
            this.yCursor = -1;
            this.xCursor = -1;
        }
        onOpened() {
            super.onOpened();
            this.buttonClose.fOnClick = () => { this.closeDialog(); };
            this.buildUi();
            this.fillData();
            this.registerListeners({
                MSG_AD_EVENT_SUCCESSD: this.onMsgAdEventSuccessed.bind(this),
            });
            mgrAd.triggerAdEvent(AD_EVENT_ID.INTER.food_shop_dialog);
            mgrTip.showNativeBanner(AD_EVENT_ID.BANNER.food_shop_dialog, this);
            this.spriteNativeEmbed.scale(0, 0);
            mgrAdNative.registerNativeBannerRefreshFun(AD_EVENT_ID.embed.food_shop_dialog, this.refreshEmbedNative.bind(this), this.spriteNativeEmbed);
        }
        onClosed() {
            super.onClosed();
        }
        buildUi() {
            this.reuseList = new ReuseList(3, 0, 10);
            this.reuseList.size(this.boxList.width, this.boxList.height);
            this.boxList.addChild(this.reuseList);
            this.reuseList.setItemClass(vFoodShopItem);
            this.reuseList.setSpaceX(25);
            this.reuseList.setSpaceY(-35);
        }
        fillData() {
            let shops = mgrShop.getAllShopItemListByCategory([Const.SHOP_FOOD_TAG]);
            let datas = [];
            for (let index = 0; index < shops.length; index++) {
                const element = shops[index];
                datas.push({
                    shopId: element.id,
                    fOnClick: this.onClickShop.bind(this),
                });
            }
            this.reuseList.setDatas(datas);
        }
        refreshEmbedNative(nativeData) {
            if (!!nativeData) {
                Tools.loadAdImg(this.spriteNativeIcon, nativeData.url);
                this.labelNativeTitle.text = nativeData.title;
                this.labelNativeGo.text = nativeData.targetTitle;
                this.labelNativeDesc.text = nativeData.desc;
                CustomTween.to(this.spriteNativeEmbed, { scaleX: 1, scaleY: 1 }, 300).start(1);
            }
            else {
                CustomTween.to(this.spriteNativeEmbed, { scaleX: 0, scaleY: 0 }, 300).start(1);
            }
        }
        onClickShop(shopId, worldPos, callback) {
            let bTriggerAd = mgrAd.preCheckCanTriggerAdEvent(AD_EVENT_ID.VIDEO.free_food);
            let recommendFoodId = mgrInteraction.getTodayRecommendFoodId();
            if (bTriggerAd && recommendFoodId == shopId) {
                this.context.adShopId = shopId;
                this.context.adCallback = callback;
                this.context.adWorldPos = worldPos;
                mgrAd.triggerAdEvent(AD_EVENT_ID.VIDEO.free_food, null, true);
                return;
            }
            else {
                callback && callback(this.buyShop(shopId, worldPos));
            }
            return false;
        }
        buyShop(shopId, worldPos, bIgnoreConsume = false) {
            let bSuccessful = mgrShop.requestBuy(shopId);
            if (bSuccessful) {
                if (this.xCursor == -1) {
                    this.xCursor = 35;
                    this.yCursor = this.boxBasket.height - 60;
                }
                else if (this.xCursor > this.boxBasket.width - 20) {
                    this.xCursor = 35;
                    this.yCursor -= (Math.random() / 2 + 0.5) * this.yDistance;
                }
                let shopData = mgrCfg.get_from_shop_template_db(shopId);
                let itemData = mgrCfg.get_from_item_template_db(shopData.items[0][0]);
                let image = new Laya.Image(itemData.icon);
                image.width = 80;
                image.height = 80;
                image.anchorX = 0.5;
                image.anchorY = 0.5;
                this.boxBasket.addChild(image);
                let localPos = this.boxBasket.globalToLocal(worldPos);
                image.pos(localPos.x, localPos.y, true);
                image.zOrder = Tools.random(1, 10);
                let pos1 = new Laya.Vector2(localPos.x, localPos.y);
                let pos2 = new Laya.Vector2((localPos.x + this.xCursor) / 2, (localPos.y + this.yCursor) / 2 - 200);
                let pos3 = new Laya.Vector2(this.xCursor, this.yCursor);
                CustomTween.bezierCurveMotion(pos1, pos2, pos3, image, 500).start(1);
                this.xCursor += (Math.random() / 2 + 0.5) * this.xDistance;
                mgrSdk.staticPointEvent(5021);
            }
            return bSuccessful;
        }
        onMsgAdEventSuccessed(e) {
            if (e.adEventId == AD_EVENT_ID.VIDEO.free_food) {
                this.context.adCallback(this.buyShop(this.context.adShopId, this.context.adWorldPos, true));
            }
        }
    }

