    class vSeedSelectDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vSeedSelectDialog";
            this.exportNodeNames = [
                "CC_boxList",
                "CC_spriteTip",
                "CC_labelFlowerName",
                "CC_spriteSuitNormal",
                "CC_spriteSuitGold",
                "CC_progressBarSuitNormal",
                "CC_labelProgressSuitNormal",
                "CC_progressBarSuitGold",
                "CC_labelProgressSuitGold",
                "CC_spritenameNormal",
                "CC_labelNameNormal",
                "CC_spritenameGold",
                "CC_labelNameGold",
                "CC_buttonGo",
                "CC_labelGo",
                "CC_buttonPlant",
                "CC_labelPlant",
                "CC_labelLevelTip",
                "CC_buttonClose",
            ];
        }
        onOpened() {
            this.buttonClose.fOnClick = () => { this.closeDialog(); };
            this.buttonGo.fOnClick = this.onTouchButtonGo.bind(this);
            this.buttonPlant.fOnClick = this.onTouchButtonSow.bind(this);
            super.onOpened();
            this.buildUi();
            this.fillData();
        }
        onClosed() {
            super.onClosed();
        }
        buildUi() {
            this.reuseList = new ReuseList(4, 0, 10);
            this.reuseList.size(this.boxList.width, this.boxList.height);
            this.boxList.addChild(this.reuseList);
            this.reuseList.setItemClass(vSeedSelectItem);
            mgrGuide.registerGuideNode(`vSeedSelectDialog.buttonPlant`, this.buttonPlant.__node);
        }
        fillData() {
            let datas = [];
            let defaultSelectSeedId;
            mgrCfg.forDb_from_seed_db((k, v) => {
                datas.push({
                    seedId: v.id,
                    fOnTouchSeed: this.onTouchSeed.bind(this),
                    fIsSelected: this.isSelected.bind(this),
                });
                if (!defaultSelectSeedId && mgrPlayer.getItemAmount(v.id) > 0) {
                    defaultSelectSeedId = v.id;
                }
            });
            this.reuseList.setDatas(datas);
            this.onTouchSeed(defaultSelectSeedId || 601);
        }
        onTouchSeed(seedId) {
            if (this.selectedSeedId == seedId)
                return;
            this.selectedSeedId = seedId;
            this.reuseList.refresh();
            let seedData = mgrCfg.get_from_seed_db(seedId);
            this.labelFlowerName.text = seedData.name;
            let [suitIdNormal, suitIdGold] = seedData.forSuitIds;
            let suitDataNormal = mgrCfg.get_from_suit_db(suitIdNormal);
            Tools.loadImg(this.spriteSuitNormal, suitDataNormal.icon);
            let suitDataGold = mgrCfg.get_from_suit_db(suitIdGold);
            Tools.loadImg(this.spriteSuitGold, suitDataGold.icon);
            this.labelNameNormal.text = suitDataNormal.name;
            this.labelNameGold.text = suitDataGold.name;
            let [cur1, max1] = mgrPart.getSuitProgress(suitIdNormal);
            let [cur2, max2] = mgrPart.getSuitProgress(suitIdGold);
            CustomTween.actionFloat(this.labelProgressSuitGold, 0, 1, 500, (value) => {
                this.progressBarSuitGold.progress = cur2 / max2 * value;
                this.progressBarSuitNormal.progress = cur1 / max1 * value;
                this.labelProgressSuitGold.text = `${Math.floor(cur2 * value)}/${max2}`;
                this.labelProgressSuitNormal.text = `${Math.floor(cur1 * value)}/${max1}`;
            }).start(1);
            let amount = mgrPlayer.getItemAmount(seedId);
            if (amount <= 0) {
                let result = mgrInteraction.getSeedRewardFromeLevelUp();
                if (!result[seedId]) {
                    this.buttonGo.__node.visible = true;
                    this.buttonPlant.__node.visible = false;
                    this.labelLevelTip.text = ``;
                }
                else {
                    this.buttonGo.__node.visible = false;
                    this.buttonPlant.__node.visible = false;
                    this.labelLevelTip.text = `${result[seedId][0].level + 1}级获得`;
                }
            }
            else {
                this.buttonGo.__node.visible = false;
                this.buttonPlant.__node.visible = true;
                this.labelLevelTip.text = ``;
            }
        }
        isSelected(seedId) {
            return this.selectedSeedId == seedId;
        }
        onTouchButtonSow() {
            this.sendMsg("MSG_SOW", { potId: this.context.potId, seedId: this.selectedSeedId });
            this.closeDialog();
            this.sendMsg("MSG_GUIDE_EVENT", { id: `vSeedSelectDialog.clickButtonPlant` });
        }
        onTouchButtonGo() {
            if (Math.random() > 0.5) {
                mgrDirector.open2DScene(`vMotionMainScene`);
            }
            else {
                mgrDirector.open2DScene(`vAnswerQuestionScene`);
            }
            this.closeDialog();
        }
    }

    class vSettingDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vSettingDialog";
            this.exportNodeNames = [
                "CC_boxMusic",
                "CC_buttonSwitchMusic",
                "CC_spriteCloseMusic",
                "CC_spriteOpenMusic",
                "CC_buttonClose",
                "CC_boxSoundEffect",
                "CC_buttonSwitchSoundEffect",
                "CC_spriteCloseSoundEffect",
                "CC_spriteOpenSoundEffect",
                "CC_boxVideoRecord",
                "CC_buttonSwitchVideoRecord",
                "CC_spriteCloseVideoRecord",
                "CC_spriteOpenVideoRecord",
                "CC_labelLebel",
            ];
        }
        onOpened() {
            super.onOpened();
            this.buttonClose.fOnClick = this.onTouchButtonClose.bind(this);
            this.buttonSwitchMusic.fOnClick = this.onTouchButtonMusic.bind(this);
            this.buttonSwitchSoundEffect.fOnClick = this.onTouchButtonSoundEffect.bind(this);
            this.buttonSwitchVideoRecord.fOnClick = this.onTouchButtonVideoRecord.bind(this);
            mgrLoader.loadFont("smallGameSettlement", this.labelLebel);
            this.fillData();
            mgrTip.showNativeBanner(AD_EVENT_ID.BANNER.setting_dialog, this);
            Tools.registerTouchHander(this, this.onTouchNodeBg.bind(this));
            mgrTip.showJumpOtherGameBanner(this);
        }
        onClosed() {
            super.onClosed();
        }
        onAnimationFinished() {
            mgrTip.showJumpOtherGameBanner(this);
        }
        onTouchButtonClose() {
            this.closeDialog();
        }
        onTouchButtonMusic() {
            let volume = mgrSound.getMusicVolmue();
            if (volume > 0) {
                mgrSound.pauseMusic("settingDialog");
            }
            else {
                mgrSound.resumeMusic("settingDialog");
            }
            this.fillData();
        }
        onTouchButtonSoundEffect() {
            let volume = mgrSound.getEffectVolume();
            if (volume > 0) {
                mgrSound.pauseEffect("settingDialog");
            }
            else {
                mgrSound.resumeEffect("settingDialog");
            }
            this.fillData();
        }
        onTouchButtonVideoRecord() {
            mgrChannel.setUserOpenVideoRecord(!mgrChannel.getUserOpenVideoRecord());
            this.fillData();
        }
        fillData() {
            this.boxVideoRecord.visible = mgrChannel.haveVideoRecord();
            let bOpenVideoRecord = mgrChannel.getUserOpenVideoRecord();
            this.spriteOpenVideoRecord.visible = bOpenVideoRecord;
            this.spriteCloseVideoRecord.visible = !bOpenVideoRecord;
            let bOpenMusic = mgrSound.getMusicVolmue() == 1;
            this.spriteOpenMusic.visible = bOpenMusic;
            this.spriteCloseMusic.visible = !bOpenMusic;
            let bOpenSoundEffect = mgrSound.getEffectVolume() == 1;
            this.spriteOpenSoundEffect.visible = bOpenSoundEffect;
            this.spriteCloseSoundEffect.visible = !bOpenSoundEffect;
            this.labelLebel.text = `${mgrInteraction.level}`;
        }
        onTouchNodeBg(e) {
            if (e.isBegin) {
                this["_b_drag_to_right"] = true;
                this["_turn_count"] = 0;
                this["_b_poped"] = false;
                this[`_v_start_pos`] = e.pos;
            }
            else if (e.isMove) {
                let p0 = this[`_v_start_pos`];
                let p = e.pos;
                if (this["_b_drag_to_right"]) {
                    if (p.x < p0.x - 20) {
                        this["_b_drag_to_right"] = false;
                        this["_turn_count"]++;
                        console.log("turn left", this["_turn_count"]);
                    }
                }
                else {
                    if (p.x > p0.x + 20) {
                        this["_b_drag_to_right"] = true;
                        this["_turn_count"]++;
                        console.log("turn right", this["_turn_count"]);
                    }
                }
                if (!this["_b_poped"]) {
                    if (this["_turn_count"] >= 10) {
                        mgrDirector.openDialog("vDebugDialog");
                        this["_b_poped"] = true;
                    }
                }
            }
        }
    }

