    class vShopPartItem extends ViewBase {
        constructor(context) {
            super(context);
            this.sourceName = "node/vShopPartItem";
            this.exportNodeNames = [
                "CC_buttonBg",
                "CC_imageIcon",
                "CC_spriteHaved",
                "CC_boxTagLayout",
                "CC_labelConsumeCount",
                "CC_spriteConsumeIcon",
                "CC_spriteTagDiscount",
            ];
            this.size(156, 184);
            this.anchorX = 0;
            this.anchorY = 0;
        }
        onOpened() {
            this.buttonBg.fOnClick = () => {
                let shopData = mgrCfg.get_from_shop_template_db(this.data.shopId);
                let itemId = shopData.items[0][0];
                if (mgrPlayer.getItemAmount(itemId) > 0) {
                    mgrTip.showMsgTip("已经购买了喔！");
                    return;
                }
                this.data && this.data.fOnClickBuy && this.data.fOnClickBuy(this.data.shopId);
            };
            this.data && this.fillByData(this.data);
        }
        onClosed() {
        }
        fillByData(data) {
            this.data = data;
            if (!this.bResLoaded)
                return;
            let shopData = mgrCfg.get_from_shop_template_db(this.data.shopId);
            let bDiscount = mgrShop.isDiscount(shopData.id);
            let itemId = shopData.items[0][0];
            let amount = shopData.items[0][1];
            let itemData = mgrCfg.get_from_item_template_db(itemId);
            Tools.loadImg(this.imageIcon, itemData.icon);
            Tools.loadImg(this.spriteConsumeIcon, mgrCfg.get_from_item_template_db(shopData.priceUnit).icon);
            this.labelConsumeCount.text = `x${shopData.price}`;
            if (bDiscount) {
                this.labelConsumeCount.text = `x${Math.floor(shopData.price / 2)}`;
            }
            this.spriteHaved.visible = mgrPlayer.getItemAmount(itemId) > 0;
            this.boxTagLayout.removeChildren(0, this.boxTagLayout.numChildren);
            let partId = this.data.shopId;
            let tagDatas = mgrPart.getRecommendTagsByPartId(partId);
            let partData = mgrCfg.get_from_part_db(partId);
            for (let index = 0; index < tagDatas.length; index++) {
                const element = tagDatas[index];
                let img = new Laya.Image;
                img.size(35 * 0.65, 35 * 0.65);
                img.pivot(img.width / 2, img.height / 2);
                Tools.loadImg(img, element.icon);
                this.boxTagLayout.addChild(img);
            }
            if (!this.starLevelNode) {
                this.starLevelNode = new vStarLevelItem({});
                this.addChild(this.starLevelNode);
                this.starLevelNode.pos(this.width / 2, 130, true);
                this.starLevelNode.scale(0.7, 0.7, true);
            }
            this.starLevelNode.fillByData(partData.level);
            this.spriteTagDiscount.visible = bDiscount;
            CustomTween.scaleForever(this.spriteTagDiscount, 1, 1.2, 500);
        }
    }

