    const AD_EVENT_ID_ENERGY_POTION = "free_energy_potion";
    class vTiredTipDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vTiredTipDialog";
            this.exportNodeNames = [
                "CC_labelContent",
                "CC_buttonClose",
                "CC_buttonUse",
                "CC_buttonBuy",
                "CC_labelPrice",
                "CC_imagePrice",
                "CC_buttonAd",
            ];
        }
        onOpened() {
            super.onOpened();
            this.buttonUse.fOnClick = this.onTouchButtonUse.bind(this);
            this.buttonBuy.fOnClick = this.onTouchButtonBuy.bind(this);
            this.buttonAd.fOnClick = this.onTouchButtonAd.bind(this);
            this.buttonClose.fOnClick = this.onTouchButtonClose.bind(this);
            mgrSound.play(209);
            this.fillData();
            this.registerListeners({
                MSG_AD_EVENT_SUCCESSD: this.onMsgAdEventSuccessed.bind(this),
            });
            mgrTip.showJumpOtherGameBanner(this);
        }
        onClosed() {
            super.onClosed();
        }
        fillData() {
            let amount = mgrPlayer.getItemAmount(Const.ITEM_ID_INTERACTION_ENERGY);
            if (amount > 0) {
                this.buttonUse.__node.visible = true;
                this.buttonBuy.__node.visible = false;
                this.buttonAd.__node.visible = false;
            }
            else {
                this.buttonUse.__node.visible = false;
                let bTriggerAd = mgrAd.preCheckCanTriggerAdEvent(AD_EVENT_ID_ENERGY_POTION);
                if (bTriggerAd) {
                    this.buttonBuy.__node.visible = false;
                    this.buttonAd.__node.visible = true;
                }
                else {
                    this.buttonBuy.__node.visible = true;
                    this.buttonAd.__node.visible = false;
                    let shopData = mgrCfg.get_from_shop_template_db(Const.ITEM_ID_INTERACTION_ENERGY);
                    this.labelPrice.text = `${shopData.price}`;
                    Tools.loadImg(this.imagePrice, mgrCfg.get_from_item_template_db(shopData.priceUnit).icon);
                }
            }
        }
        onTouchButtonUse() {
            mgrInteraction.eatFood(Const.ITEM_ID_INTERACTION_ENERGY);
            this.closeDialog();
        }
        onTouchButtonBuy() {
            if (mgrShop.requestBuy(Const.ITEM_ID_INTERACTION_ENERGY)) {
                this.fillData();
            }
        }
        onTouchButtonAd() {
            mgrAd.triggerAdEvent(AD_EVENT_ID_ENERGY_POTION, null, true);
        }
        onTouchButtonClose() {
            this.closeDialog();
        }
        onMsgAdEventSuccessed(e) {
            if (e.adEventId == AD_EVENT_ID_ENERGY_POTION) {
                mgrPlayer.addItemAmount(Const.ITEM_ID_INTERACTION_ENERGY, 1, "看广告获得饥饿药水");
                mgrInteraction.eatFood(Const.ITEM_ID_INTERACTION_ENERGY);
                this.closeDialog();
            }
        }
    }

    class vTryAgainDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vTryAgainDialog";
            this.exportNodeNames = [
                "CC_labelContent",
                "CC_buttonClose",
                "CC_buttonConsume",
                "CC_labelConsumeCount",
                "CC_imageConsumeIcon",
                "CC_buttonWatchAd",
                "CC_labelWatchAd",
                "CC_progressBar",
                "CC_spriteTipPoint",
            ];
        }
        onOpened() {
            super.onOpened();
            this.buttonConsume.__node.visible = false;
            this.buttonWatchAd.fOnClick = this.onTouchButtonAd.bind(this);
            this.buttonConsume.fOnClick = this.onTouchButtonBuy.bind(this);
            this.buttonClose.fOnClick = this.onTouchButtonBack.bind(this);
            this.progressBar.barName = `bar`;
            this.progressBar.style = ULPROGRESSBAR_STYLE.fan;
            this.fillData();
            this.registerListeners({
                MSG_AD_EVENT_SUCCESSD: this.onMsgAdEventSuccessed.bind(this),
            });
        }
        onClosed() {
            super.onClosed();
        }
        fillData() {
            let adEventId = this.context.adEventId;
            let bTrigger = mgrAd.preCheckCanTriggerAdEvent(adEventId);
            this.buttonWatchAd.__node.visible = bTrigger;
            let consume = this.context.consume;
            this.labelConsumeCount.text = `${consume.amount}`;
            Tools.loadImg(this.imageConsumeIcon, mgrCfg.get_from_item_template_db(consume.itemId).icon);
            this.progressTween = CustomTween.actionFloat(this.progressBar.__node, 0, 1, 5000, (value) => {
                this.progressBar.progress = value;
                this.spriteTipPoint.rotation = value * 360;
            })
                .callback(() => {
                this.onTouchButtonBack();
            })
                .start(1);
            2;
        }
        onTouchButtonAd() {
            this.progressTween.clear();
            mgrAd.triggerAdEvent(this.context.adEventId, null, true);
        }
        onTouchButtonBuy() {
            if (mgrPlayer.getItemAmount(this.context.consume.itemId) < this.context.consume.amount) {
                mgrShop.tipItemNotEnough(this.context.consume.itemId);
                return;
            }
            mgrPlayer.addItemAmount(this.context.consume.itemId, -this.context.consume.amount, "复活消耗");
            this.context.buyCallback && this.context.buyCallback();
            this.closeDialog();
        }
        onTouchButtonBack() {
            this.context.cancleCallback && this.context.cancleCallback();
            this.closeDialog();
        }
        onMsgAdEventSuccessed(e) {
            if (e.adEventId == this.context.adEventId) {
                this.context.onAdCallback && this.context.onAdCallback();
                this.closeDialog();
                if (this.context.adEventId == AD_EVENT_ID.VIDEO.playBallTryAgain) {
                    mgrSdk.staticPointEvent(5010);
                }
                if (this.context.adEventId == AD_EVENT_ID.VIDEO.ropeSkippingTryAgain) {
                    mgrSdk.staticPointEvent(5009);
                }
            }
        }
    }

