    class vWishDialog extends DialogBase {
        constructor(context) {
            super(context);
            this.sourceName = "dialog/vWishDialog";
            this.exportNodeNames = [
                "CC_spriteBg",
                "CC_spriteCenterPos",
            ];
            this.bFadingOut = false;
            this.parentObjects = [];
            this.castTrials = [];
            this.bEnded = false;
            this.dirCount = Tools.random(3, 5);
        }
        onOpened() {
            super.onOpened();
            Tools.registerTouchHander(this.spriteBg, this.onTouchSpriteBg.bind(this));
            this.buildScene();
            this.fadeIn();
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_xuyuanchi_fz, this.spriteCenterPos, 0);
        }
        onClosed() {
            super.onClosed();
        }
        getPreLoadModelIds() {
            return [MODEL_ID.wish_cast_trail, MODEL_ID.effect.eff_ui_xuyuanchi_fz, MODEL_ID.effect.eff_ui_xuyuanchi_bz];
        }
        fadeIn() {
            this.spriteBg.alpha = 0;
            CustomTween.to(this.spriteBg, { alpha: 1 }, 500).start(1);
        }
        isShowShadow() {
            return false;
        }
        fadeOut() {
            if (this.bFadingOut)
                return;
            this.bFadingOut = true;
            CustomTween.to(this.spriteBg, { alpha: 0 }, 300)
                .callback(() => {
                this.closeDialog(true);
            })
                .start(1);
        }
        buildScene() {
            this.spriteBg.zOrder = -2;
            this.colliderBox = new Laya.MeshSprite3D(Laya.PrimitiveMesh.createBox(10, 20, 0.01));
            this.colliderBox.meshRenderer.enable = false;
            let collider = this.colliderBox.addComponent(Laya.PhysicsCollider);
            let colliderShape = new Laya.BoxColliderShape(10, 20, 0.01);
            collider.colliderShape = colliderShape;
            this.add3DEffectAtFront(this.colliderBox, this.spriteCenterPos, 0);
            this.cameraFront.transform.position = new Laya.Vector3(0, 0, 10);
        }
        onTouchSpriteBg(e) {
            if (this.bEnded)
                return;
            if (e.isBegin) {
                for (let i = 1; i <= this.dirCount; i++) {
                    let po = new Laya.Sprite3D;
                    po.name = `po`;
                    this.add3DEffectAtFront(po, this.spriteCenterPos, 0);
                    let trial = mgrLoader.Pool.getModel(MODEL_ID.wish_cast_trail);
                    this.link2Node(po, trial, po.name);
                    this.parentObjects.push(po);
                    this.castTrials.push(trial);
                    po.transform.rotationEuler = new Laya.Vector3(0, 0, 360 / this.dirCount * i);
                }
                this.syncTrail(new Laya.Vector2(e.pos.x, e.pos.y));
                for (let index = 0; index < this.castTrials.length; index++) {
                    const element = this.castTrials[index];
                    let trail1 = element.getChildAt(0);
                    trail1.trailFilter.time = 5;
                    let trial2 = element.getChildAt(0).getChildAt(0);
                    trial2.trailFilter.time = 5;
                }
            }
            else if (e.isMove) {
                this.syncTrail(new Laya.Vector2(e.pos.x, e.pos.y));
            }
            else if (e.isEnd) {
                this.bEnded = true;
                for (let index = 0; index < this.castTrials.length; index++) {
                    const element = this.castTrials[index];
                    let trail1 = element.getChildAt(0);
                    trail1.trailFilter.time = 2;
                    let trial2 = element.getChildAt(0).getChildAt(0);
                    trial2.trailFilter.time = 2;
                    CustomTween.actionFloat(element.transform, 0, 1, 500, (value) => {
                        element.transform.localPosition = new Laya.Vector3(element.transform.localPosition.x * (1 - value), element.transform.localPosition.y * (1 - value), element.transform.localPosition.z * (1 - value));
                    }).start(1);
                }
                Timer.callLater(2, () => {
                    this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_xuyuanchi_bz, this.spriteCenterPos, 0);
                    Timer.callLater(0.1, () => {
                        this.context.fOnFinish();
                        Timer.callLoop(0.016, (timer) => {
                            if (DialogBase.ShowingDialog.length == 1) {
                                timer.stop();
                                this.fadeOut();
                            }
                        }, this);
                    }, this);
                }, this);
            }
        }
        syncTrail(screenPos) {
            let o = Tools.castRayFromScreenPos(this.scene3DFront, this.cameraFront, screenPos);
            if (o.succeeded) {
                this.castTrials[0].transform.position = o.point.clone();
                for (let i = 1; i <= this.dirCount - 1; i++) {
                    let trial = this.castTrials[i];
                    trial.transform.localPosition = this.castTrials[0].transform.localPosition.clone();
                }
            }
        }
    }

    class vChapterNode extends ViewBase {
        constructor(context) {
            super(context);
            this.sourceName = "node/vChapterNode";
            this.exportNodeNames = [
                "CC_buttonStage1",
                "CC_buttonStage2",
                "CC_buttonStage3",
                "CC_buttonStage4",
                "CC_buttonStage5",
                "CC_buttonStage6",
                "CC_buttonStage7",
                "CC_buttonStage8",
                "CC_spriteEffect1",
                "CC_spriteEffect2",
                "CC_spriteEffect3",
                "CC_spriteEffect4",
                "CC_spriteEffect5",
            ];
            this.width = 768;
            this.height = 1280;
            this.anchorX = 0;
            this.anchorY = 0;
            this.registerListeners({
                MSG_PLAY_FINISH_ANIMATION: this.onMsgPlayFinishAnimation.bind(this),
            });
        }
        onOpened() {
            if (this.data)
                this.fillByData(this.data);
            if (this.calledPlayFinishAnimation)
                this.onMsgPlayFinishAnimation(this.calledPlayFinishAnimation);
            this.addEffect();
        }
        onClosed() {
        }
        addEffect() {
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_tree_star, this.spriteEffect1, 0);
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_tree_star, this.spriteEffect2, 0);
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_tree_star, this.spriteEffect3, 0);
            this.add3DEffectAtFront(MODEL_ID.effect.eff_ui_tree_star, this.spriteEffect5, 0);
        }
        fillByData(data) {
            this.data = data;
            if (!this.bResLoaded)
                return;
            let chapterData = mgrCfg.get_from_stage_chapter_db(this.data.chapterId);
            for (let i = 0; i < chapterData.stageIds.length; i++) {
                const stageId = chapterData.stageIds[i];
                let stageData = mgrCfg.get_from_stage_db(stageId);
                let bHaveStory = !!stageData.storyId;
                let bPassed = mgrStage.getStageRating(stageId) == EStageRating.pass;
                let [rewardItemId, rewardAmount] = stageData.passReward[stageData.passReward.length - 1];
                let bPart = rewardItemId >= 10000;
                let parent = this[`buttonStage${i + 1}`].__node;
                let paopao = parent.getChildByName("paopao");
                let light = parent.getChildByName("light");
                let name = parent.getChildByName("labelName");
                let icon = paopao.getChildByName("icon");
                let gou = paopao.getChildByName("gou");
                let buttonReviewNode = paopao.getChildByName("buttonReview");
                let button = buttonReviewNode.addComponent(ScaleButton);
                let bg2 = parent.getChildByName("bg2");
                mgrGuide.registerGuideNode(`vStageScene.stage${stageId}`, parent);
                button.fOnClick = () => {
                    this.onReviewStage(stageId);
                };
                this[`buttonStage${i + 1}`].fOnClick = () => {
                    this.onClickStage(stageId);
                };
                light.visible = !bPassed && bPart;
                CustomTween.rotateForever(light);
                name.text = `第${stageId}关`;
                icon.visible = !bPassed;
                Tools.loadImg(icon, mgrCfg.get_from_item_template_db(rewardItemId).icon);
                buttonReviewNode.visible = bPassed && bHaveStory;
                gou.visible = bPassed;
                if (mgrStage.getCurrentStageId() == stageId) {
                    CustomTween.scaleForever(bg2, 1, 1.2, 700);
                    CustomTween.scaleForever(name, 1, 1.2, 700);
                }
            }
        }
        onReviewStage(stageId) {
            this.data.onReviewStage && this.data.onReviewStage(stageId);
        }
        onClickStage(stageId) {
            this.sendMsg("MSG_GUIDE_EVENT", { id: `vStageScene.clickStage${stageId}` });
            this.data.onClickStage && this.data.onClickStage(stageId);
        }
        onMsgPlayFinishAnimation(e) {
            this.calledPlayFinishAnimation = e;
            if (!this.bResLoaded)
                return;
            let chapterData = mgrCfg.get_from_stage_chapter_db(this.data.chapterId);
            let index = chapterData.stageIds.indexOf(e.stageId);
            if (index == -1)
                return;
            const stageId = e.stageId;
            let stageData = mgrCfg.get_from_stage_db(stageId);
            let bHaveStory = !!stageData.storyId;
            let bPassed = false;
            let [rewardItemId, rewardAmount] = stageData.passReward[stageData.passReward.length - 1];
            let bPart = rewardItemId >= 10000;
            let parent = this[`buttonStage${index + 1}`].__node;
            let paopao = parent.getChildByName("paopao");
            let light = parent.getChildByName("light");
            let name = parent.getChildByName("labelName");
            let icon = paopao.getChildByName("icon");
            let gou = paopao.getChildByName("gou");
            let bg2 = parent.getChildByName("bg2");
            let buttonReviewNode = paopao.getChildByName("buttonReview");
            light.visible = !bPassed && bPart;
            CustomTween.rotateForever(light);
            name.text = `第${stageId}关`;
            icon.visible = !bPassed;
            Tools.loadImg(icon, mgrCfg.get_from_item_template_db(rewardItemId).icon);
            buttonReviewNode.visible = bPassed && bHaveStory;
            gou.visible = bPassed;
            CustomTween.to(light, { scaleX: 0, scaleY: 0 }, 300).start(1);
            CustomTween.to(paopao, { scaleX: 0, scaleY: 0 }, 300)
                .delayTime(1000)
                .callback(() => {
                bPassed = true;
                light.visible = !bPassed && bPart;
                CustomTween.rotateForever(light);
                name.text = `第${stageId}关`;
                icon.visible = !bPassed;
                Tools.loadImg(icon, mgrCfg.get_from_item_template_db(rewardItemId).icon);
                buttonReviewNode.visible = bPassed && bHaveStory;
                gou.visible = bPassed;
            })
                .to({ scaleX: 1, scaleY: 1 }, 300, Laya.Ease.backOut)
                .start(1);
            if (mgrStage.getCurrentStageId() == stageId) {
                CustomTween.scaleForever(bg2, 1, 1.2, 700);
                CustomTween.scaleForever(name, 1, 1.2, 700);
            }
        }
    }

