    class vEditorDynamicBoneChild extends ViewBase {
        constructor(context) {
            super(context);
            this.sourceName = "node/vEditorDynamicBoneChild";
            this.exportNodeNames = [
                "CC_buttonBg",
                "CC_labelContent",
            ];
            this.width = 200;
            this.height = 65;
            this.anchorX = 0;
            this.anchorY = 0;
        }
        onOpened() {
            this.buttonBg.fOnClick = () => {
                this.data.onClickNode && this.data.onClickNode(this.data.node);
            };
            this.data && this.fillByData(this.data);
        }
        onClosed() {
        }
        fillByData(data) {
            this.data = data;
            if (!this.bResLoaded)
                return;
            this.labelContent.text = this.data.node.name;
            let router = this.generateRoute(this.data.node, this.data.model);
            let b = mgrMaterial.hasDynamicBone(this.data.model[`__modelId`], router);
            b ? this.labelContent.color = `#00ff00` : this.labelContent.color = `#ff0000`;
        }
        generateRoute(child, parent) {
            if (child == parent)
                return "/";
            let routes = [];
            while (true) {
                routes.push(child.name);
                child = child.parent;
                if (child == parent)
                    break;
            }
            let router = "/";
            for (let i = routes.length - 1; i >= 0; i--) {
                router += `${routes[i]}`;
                if (i != 0) {
                    router += "/";
                }
            }
            return router;
        }
    }

