            this.cameraBack.fieldOfView = 25;
            this.cameraBack.getComponent(CameraFollow).distance = new Laya.Vector3(0.1, 0.80, 5);
            this.cameraBack.getComponent(CameraFollow).endRotation = new Laya.Vector3(-4.00, 0, 0);
