            CustomTween.to(this.imageMaskLeft, { alpha: 0 }, 300).start(1);
            CustomTween.to(this.imageMaskRight, { alpha: 0 }, 300).start(1);
            CustomTween.to(this.imageMaskCenter, { alpha: 0 }, 300).start(1);
            Timer.callLater(0.3, () => {
                super.closeDialog(true);
            });
